import React, { useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import { 
  Menu, X, Globe, Star, ChevronLeft, ChevronRight, 
  Settings, Save, Plus, Trash2, Send, CheckCircle2,
  Home, Building2, Paintbrush, ShieldCheck, MapPin, Phone, Mail
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

// --- Types ---
type Language = 'PT' | 'EN' | 'ES';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface Review {
  id: number;
  author: string;
  rating: number;
  text: string;
  date: string;
}

// --- Translations ---
const translations = {
  PT: {
