    alTitle: "Alojamentos Locais",
    alDesc: "Gestão completa de limpeza para o seu alojamento local com padrão de hotelaria.",
    postTitle: "Pós Obras",
    postDesc: "Limpeza técnica e profunda para deixar seu imóvel novo pronto a habitar.",
    privateTitle: "Propriedades Particulares",
    privateDesc: "Cuidado exclusivo e minucioso para residências de alto padrão.",
    otherTitle: "Manutenção Geral",
    otherDesc: "Soluções personalizadas para condomínios e espaços comerciais.",
    reviewsTitle: "O que dizem nossos clientes",
    quoteTitle: "Solicite um Orçamento",
    name: "Nome",
    email: "Email",
    phone: "Telefone",
    message: "Mensagem",
    send: "Enviar Pedido",
    adminTitle: "Painel Administrativo",
    adminPass: "Senha de Acesso",
    save: "Salvar Alterações",
    success: "Mensagem enviada com sucesso!",
    footerInfo: "Informações",
    footerContact: "Contacto",
    footerLinks: "Links Rápidos"
  },
  EN: {
    navHome: "Home",
    navServices: "Services",
    navReviews: "Reviews",
    navContact: "Quote",
    heroSubtitle: "Luxury Cleaning in the Golden Triangle",
    servicesTitle: "Our Specialized Services",
    alTitle: "Local Accommodation",
    alDesc: "Complete cleaning management for your rental property with hotel standards.",
    postTitle: "Post-Construction",
    postDesc: "Technical and deep cleaning to make your new property ready to move in.",
    privateTitle: "Private Properties",
    privateDesc: "Exclusive and meticulous care for high-end residences.",
    otherTitle: "General Maintenance",
    otherDesc: "Customized solutions for condominiums and commercial spaces.",
    reviewsTitle: "What our clients say",
    quoteTitle: "Request a Quote",
    name: "Name",
    email: "Email",
    phone: "Phone",
    message: "Message",
    send: "Send Request",
    adminTitle: "Admin Panel",
    adminPass: "Access Password",
    save: "Save Changes",
    success: "Message sent successfully!",
    footerInfo: "Information",
    footerContact: "Contact",
    footerLinks: "Quick Links"
  },
  ES: {
    navHome: "Inicio",
    navServices: "Servicios",
    navReviews: "Reseñas",
    navContact: "Presupuesto",
    heroSubtitle: "Limpieza de Lujo en el Triángulo Dorado",
    servicesTitle: "Nuestros Servicios Especializados",
    alTitle: "Alojamiento Local",
    alDesc: "Gestión completa de limpieza para su alquiler con estándares de hotel.",
    postTitle: "Post-Construcción",
    postDesc: "Limpieza técnica y profunda para dejar su nueva propiedad lista para habitar.",
    privateTitle: "Propiedades Privadas",
    privateDesc: "Cuidado exclusivo y minucioso para residencias de lujo.",
    otherTitle: "Mantenimiento General",
    otherDesc: "Soluciones personalizadas para condominios y espacios comerciales.",
    reviewsTitle: "Lo que dicen nuestros clientes",
    quoteTitle: "Solicite un Presupuesto",
    name: "Nombre",
    email: "Correo",
    phone: "Teléfono",
    message: "Mensaje",
    send: "Enviar Solicitud",
    adminTitle: "Panel Administrativo",
    adminPass: "Contraseña de Acceso",
    save: "Guardar Cambios",
    success: "¡Mensaje enviado con éxito!",
    footerInfo: "Información",
    footerContact: "Contacto",
    footerLinks: "Enlaces Rápidos"
  }
};

const DEFAULT_SLIDES: Slide[] = [
  { 
    id: '1', 
    title: "Excelência em cada detalhe", 
    description: "Focados nas propriedades mais exclusivas do Algarve.", 
    image: "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&q=80&w=1200",
    tag: "Luxo"
  },
  { 
    id: '2', 
    title: "Serviços Pós-Obra", 
    description: "Equipas especializadas para grandes projetos.", 
    image: "https://images.unsplash.com/photo-1581578731548-c64695cc6954?auto=format&fit=crop&q=80&w=1200",
    tag: "Técnico"
  }
];

const REVIEWS: Review[] = [
  { id: 1, author: "John Smith", rating: 5, text: "Excellent service in Quinta do Lago. Very professional and detail-oriented.", date: "2 weeks ago" },
  { id: 2, author: "Maria Silva", rating: 5, text: "A melhor empresa de limpezas que já contratei para o meu AL em Vilamoura.", date: "1 month ago" },
  { id: 3, author: "Elena Rodriguez", rating: 5, text: "Servicio impecable. Mi casa de Vale do Lobo siempre está perfecta.", date: "3 days ago" }
];

const App = () => {
  const [lang, setLang] = useState<Language>('PT');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [adminPass, setAdminPass] = useState("");
  const [isAuthorized, setIsAuthorized] = useState(false);
  const [slides, setSlides] = useState<Slide[]>(() => {
    const saved = localStorage.getItem('rosimeire_slides');
    return saved ? JSON.parse(saved) : DEFAULT_SLIDES;
  });
  const [currentSlide, setCurrentSlide] = useState(0);
  const [formStatus, setFormStatus] = useState<'idle' | 'sending' | 'success'>('idle');

  const t = translations[lang];

  // Auto-slide
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentSlide(prev => (prev + 1) % slides.length);
    }, 6000);
    return () => clearInterval(interval);
  }, [slides]);

  const handleAdminAuth = () => {
    if (adminPass === "admin123") {
      setIsAuthorized(true);
    }
  };

  const handleSaveSlides = (newSlides: Slide[]) => {
    setSlides(newSlides);
    localStorage.setItem('rosimeire_slides', JSON.stringify(newSlides));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFormStatus('sending');
    setTimeout(() => {
      setFormStatus('success');
      setTimeout(() => setFormStatus('idle'), 5000);
    }, 1500);
  };

  return (
    <div className="min-h-screen flex flex-col">
      {/* Header */}
      <header className="fixed w-full z-50 glass bg-white/70 backdrop-blur-md">
        <div className="container mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-pink-500 rounded-lg flex items-center justify-center text-white font-bold text-xl shadow-lg">R</div>
            <span className="text-2xl font-bold tracking-tighter text-blue-900">ROSIMEIRE<span className="text-pink-500">SERVIÇOS</span></span>
          </div>

          {/* Desktop Nav */}
          <nav className="hidden md:flex items-center gap-8">
            <a href="#home" className="hover:text-pink-500 transition-colors font-medium">{t.navHome}</a>
            <a href="#services" className="hover:text-pink-500 transition-colors font-medium">{t.navServices}</a>
            <a href="#reviews" className="hover:text-pink-500 transition-colors font-medium">{t.navReviews}</a>
            <a href="#quote" className="bg-gradient-to-r from-blue-600 to-pink-500 text-white px-6 py-2 rounded-full font-semibold hover:opacity-90 transition-all shadow-md">{t.navContact}</a>

            <div className="flex items-center gap-3 ml-4 border-l pl-6 border-gray-200">
              <button onClick={() => setLang('PT')} title="Português" className={`hover:scale-110 transition-transform ${lang === 'PT' ? 'ring-2 ring-pink-500 rounded-sm' : ''}`}>🇵🇹</button>
              <button onClick={() => setLang('EN')} title="English" className={`hover:scale-110 transition-transform ${lang === 'EN' ? 'ring-2 ring-pink-500 rounded-sm' : ''}`}>🇬🇧</button>
              <button onClick={() => setLang('ES')} title="Español" className={`hover:scale-110 transition-transform ${lang === 'ES' ? 'ring-2 ring-pink-500 rounded-sm' : ''}`}>🇪🇸</button>
              <button onClick={() => setIsAdminOpen(true)} className="text-gray-400 hover:text-blue-600 transition-colors"><Settings size={20} /></button>
            </div>
          </nav>

          {/* Mobile Menu Toggle */}
          <button className="md:hidden text-blue-900" onClick={() => setIsMenuOpen(!isMenuOpen)}>
            {isMenuOpen ? <X size={28} /> : <Menu size={28} />}
          </button>
        </div>
      </header>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.div 
            initial={{ opacity: 0, y: -20 }} 
            animate={{ opacity: 1, y: 0 }} 
            exit={{ opacity: 0, y: -20 }}
            className="fixed inset-0 z-40 bg-white md:hidden pt-24 px-6"
          >
            <div className="flex flex-col gap-6 text-xl font-semibold text-blue-900">
              <a href="#home" onClick={() => setIsMenuOpen(false)}>{t.navHome}</a>
              <a href="#services" onClick={() => setIsMenuOpen(false)}>{t.navServices}</a>
              <a href="#reviews" onClick={() => setIsMenuOpen(false)}>{t.navReviews}</a>
              <a href="#quote" onClick={() => setIsMenuOpen(false)} className="text-pink-500">{t.navContact}</a>
              <div className="flex gap-4 pt-6">
                <button onClick={() => setLang('PT')} className="text-3xl">🇵🇹</button>
                <button onClick={() => setLang('EN')} className="text-3xl">🇬🇧</button>
                <button onClick={() => setLang('ES')} className="text-3xl">🇪🇸</button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <main className="flex-grow">
        {/* Hero Slider */}
        <section id="home" className="relative h-[80vh] overflow-hidden mt-16">
          <AnimatePresence mode="wait">
            <motion.div
              key={currentSlide}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 1 }}
              className="absolute inset-0"
            >
              <div 
                className="absolute inset-0 bg-cover bg-center transition-transform duration-[10000ms] scale-110" 
                style={{ backgroundImage: `url(${slides[currentSlide].image})` }}
              />
              <div className="absolute inset-0 bg-gradient-to-r from-blue-900/80 to-transparent" />
              <div className="container mx-auto px-6 h-full flex flex-col justify-center relative z-10">
                <motion.span 
                  initial={{ x: -20, opacity: 0 }} 
                  animate={{ x: 0, opacity: 1 }}
                  className="bg-pink-500 text-white px-4 py-1 rounded-full text-sm font-bold w-fit mb-4"
                >
                  {slides[currentSlide].tag}
                </motion.span>
                <motion.h1 
                  initial={{ y: 20, opacity: 0 }}
                  animate={{ y: 0, opacity: 1 }}
                  className="text-5xl md:text-7xl font-bold text-white max-w-2xl mb-4 leading-tight"
                >
                  {slides[currentSlide].title}
                </motion.h1>
                <motion.p 
                  initial={{ y: 20, opacity: 0 }}
                  animate={{ y: 0, opacity: 1 }}
                  transition={{ delay: 0.2 }}
                  className="text-xl text-blue-100 max-w-lg mb-8"
                >
                  {slides[currentSlide].description}
                </motion.p>
                <div className="flex gap-4">
                  <a href="#quote" className="bg-white text-blue-900 px-8 py-3 rounded-full font-bold hover:bg-pink-500 hover:text-white transition-all shadow-xl">{t.navContact}</a>
                  <button onClick={() => setCurrentSlide((currentSlide - 1 + slides.length) % slides.length)} className="p-3 border border-white/30 rounded-full text-white hover:bg-white/20"><ChevronLeft /></button>
                  <button onClick={() => setCurrentSlide((currentSlide + 1) % slides.length)} className="p-3 border border-white/30 rounded-full text-white hover:bg-white/20"><ChevronRight /></button>
                </div>
              </div>
            </motion.div>
          </AnimatePresence>
        </section>

        {/* Dynamic Light Background Decor */}
        <div className="relative overflow-hidden">
          <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-pink-500/10 rounded-full blur-[120px] pointer-events-none" />
          <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-500/10 rounded-full blur-[120px] pointer-events-none" />

          {/* Services */}
          <section id="services" className="py-24 container mx-auto px-6 relative z-10">
            <div className="text-center mb-16">
              <h2 className="text-4xl font-bold text-blue-900 mb-4">{t.servicesTitle}</h2>
              <div className="w-24 h-1 bg-gradient-to-r from-blue-600 to-pink-500 mx-auto" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
              {[
                { icon: <Home className="text-pink-500" />, title: t.alTitle, desc: t.alDesc },
                { icon: <Paintbrush className="text-blue-600" />, title: t.postTitle, desc: t.postDesc },
                { icon: <Building2 className="text-pink-500" />, title: t.privateTitle, desc: t.privateDesc },
                { icon: <ShieldCheck className="text-blue-600" />, title: t.otherTitle, desc: t.otherDesc }
              ].map((s, idx) => (
                <div key={idx} className="glass p-8 rounded-2xl glow-hover transition-all duration-300 group">
                  <div className="mb-6 p-4 bg-white/50 rounded-xl w-fit group-hover:scale-110 transition-transform">
                    {s.icon}
                  </div>
                  <h3 className="text-xl font-bold text-blue-900 mb-3">{s.title}</h3>
                  <p className="text-gray-600 leading-relaxed">{s.desc}</p>
                </div>
              ))}
            </div>
          </section>

          {/* Reviews */}
          <section id="reviews" className="py-24 bg-blue-900 text-white relative overflow-hidden">
             <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]" />
             <div className="container mx-auto px-6 relative z-10">
                <div className="flex flex-col md:flex-row justify-between items-end mb-16 gap-4">
                  <div>
                    <h2 className="text-4xl font-bold mb-4">{t.reviewsTitle}</h2>
                    <div className="flex items-center gap-1 text-yellow-400">
                      {[...Array(5)].map((_, i) => <Star key={i} fill="currentColor" size={24} />)}
                      <span className="ml-2 text-white/80 font-medium">5.0 Google Rating</span>
                    </div>
                  </div>
                  <a href="https://google.com" target="_blank" className="text-pink-400 hover:text-pink-300 font-semibold underline underline-offset-4">View all reviews</a>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  {REVIEWS.map(r => (
                    <div key={r.id} className="bg-white/10 backdrop-blur-lg p-8 rounded-3xl border border-white/10 shimmer">
                      <div className="flex items-center gap-3 mb-6">
                        <div className="w-12 h-12 bg-gradient-to-tr from-pink-500 to-blue-500 rounded-full flex items-center justify-center font-bold">{r.author[0]}</div>
                        <div>
                          <h4 className="font-bold">{r.author}</h4>
                          <p className="text-sm text-white/60">{r.date}</p>
                        </div>
                      </div>
                      <p className="italic text-lg text-blue-50 text-white/90">"{r.text}"</p>
                    </div>
                  ))}
                </div>
             </div>
          </section>

          {/* Quote Form */}
          <section id="quote" className="py-24 container mx-auto px-6">
            <div className="glass p-8 md:p-16 rounded-[40px] shadow-2xl flex flex-col md:flex-row gap-16 items-center border border-white/50">
              <div className="flex-1">
                <h2 className="text-5xl font-bold text-blue-900 mb-6 leading-tight">{t.quoteTitle}</h2>
                <p className="text-xl text-gray-600 mb-8">Transformamos a sua propriedade no Algarve com um padrão de limpeza inigualável. Entre em contacto hoje mesmo.</p>

                <div className="space-y-6">
                  <div className="flex items-center gap-4 text-blue-900">
                    <div className="p-3 bg-blue-100 rounded-full"><MapPin className="text-blue-600" /></div>
                    <span className="font-semibold">Vilamoura / Quinta do Lago / Vale do Lobo</span>
                  </div>
                  <div className="flex items-center gap-4 text-blue-900">
                    <div className="p-3 bg-pink-100 rounded-full"><Phone className="text-pink-500" /></div>
                    <span className="font-semibold">+351 9xx xxx xxx</span>
                  </div>
                  <div className="flex items-center gap-4 text-blue-900">
                    <div className="p-3 bg-blue-100 rounded-full"><Mail className="text-blue-600" /></div>
                    <span className="font-semibold">geral@rosimeireservicos.com</span>
                  </div>
                </div>
              </div>

              <div className="flex-1 w-full">
                <form onSubmit={handleSubmit} className="space-y-4">
                  <input required type="text" placeholder={t.name} className="w-full p-4 rounded-xl border border-gray-200 focus:ring-2 focus:ring-pink-500 outline-none transition-all" />
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input required type="email" placeholder={t.email} className="w-full p-4 rounded-xl border border-gray-200 focus:ring-2 focus:ring-pink-500 outline-none transition-all" />
                    <input type="tel" placeholder={t.phone} className="w-full p-4 rounded-xl border border-gray-200 focus:ring-2 focus:ring-pink-500 outline-none transition-all" />
                  </div>
                  <textarea required placeholder={t.message} rows={4} className="w-full p-4 rounded-xl border border-gray-200 focus:ring-2 focus:ring-pink-500 outline-none transition-all" />

                  <button 
                    disabled={formStatus !== 'idle'}
                    className={`w-full py-4 rounded-xl font-bold text-white text-lg transition-all shadow-lg flex items-center justify-center gap-2 ${formStatus === 'success' ? 'bg-green-500' : 'bg-gradient-to-r from-blue-700 to-pink-500 hover:scale-[1.02]'}`}
                  >
                    {formStatus === 'idle' && <><Send size={20} /> {t.send}</>}
                    {formStatus === 'sending' && "..."}
                    {formStatus === 'success' && <><CheckCircle2 size={20} /> {t.success}</>}
                  </button>
                </form>
              </div>
            </div>
          </section>
        </div>
      </main>

      {/* Footer */}
      <footer className="bg-blue-900 text-white pt-16 pb-8 border-t border-white/10">
        <div className="container mx-auto px-6 grid grid-cols-1 md:grid-cols-4 gap-12 mb-12">
          <div className="col-span-1 md:col-span-2">
            <div className="flex items-center gap-2 mb-6">
              <div className="w-8 h-8 bg-white text-blue-900 rounded flex items-center justify-center font-bold">R</div>
              <span className="text-xl font-bold uppercase tracking-widest">Rosimeire <span className="text-pink-400">Serviços</span></span>
            </div>
            <p className="text-blue-100 max-w-sm mb-6">Líderes em limpezas residenciais de luxo no Algarve há mais de uma década. Dedicação, confiança e perfeccionismo.</p>
            <div className="flex gap-4">
               {/* Social Icons Placeholders */}
               <div className="w-10 h-10 bg-white/10 rounded-full hover:bg-pink-500 transition-colors flex items-center justify-center cursor-pointer">Ig</div>
               <div className="w-10 h-10 bg-white/10 rounded-full hover:bg-pink-500 transition-colors flex items-center justify-center cursor-pointer">Fb</div>
            </div>
          </div>

          <div>
            <h4 className="font-bold text-lg mb-6">{t.footerLinks}</h4>
            <ul className="space-y-3 text-blue-100">
              <li><a href="#home" className="hover:text-pink-400 transition-colors">{t.navHome}</a></li>
              <li><a href="#services" className="hover:text-pink-400 transition-colors">{t.navServices}</a></li>
              <li><a href="#reviews" className="hover:text-pink-400 transition-colors">{t.navReviews}</a></li>
              <li><a href="#quote" className="hover:text-pink-400 transition-colors">{t.navContact}</a></li>
            </ul>
          </div>

          <div>
            <h4 className="font-bold text-lg mb-6">{t.footerContact}</h4>
            <ul className="space-y-4 text-blue-100 text-sm">
              <li className="flex items-start gap-3">
                <MapPin size={18} className="text-pink-400 mt-1 flex-shrink-0" />
                <span>Rua Principal, Vilamoura<br/>8125-406 Loulé, Algarve</span>
              </li>
              <li className="flex items-center gap-3">
                <Phone size={18} className="text-pink-400 flex-shrink-0" />
                <span>+351 9xx xxx xxx</span>
              </li>
              <li className="flex items-center gap-3">
                <Mail size={18} className="text-pink-400 flex-shrink-0" />
                <span>info@rosimeireservicos.pt</span>
              </li>
            </ul>
          </div>
        </div>
        <div className="container mx-auto px-6 pt-8 border-t border-white/5 flex flex-col md:flex-row justify-between items-center text-xs text-blue-200 gap-4">
          <p>&copy; 2024 Rosimeire Serviços. Todos os direitos reservados.</p>
          <div className="flex gap-6">
            <a href="#" className="hover:text-white transition-colors">Política de Privacidade</a>
            <a href="#" className="hover:text-white transition-colors">Termos de Uso</a>
            <a href="#" className="hover:text-white transition-colors">Livro de Reclamações</a>
          </div>
        </div>
      </footer>

      {/* Admin Panel Modal */}
      <AnimatePresence>
        {isAdminOpen && (
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] flex items-center justify-center p-4"
          >
            <div className="absolute inset-0 bg-blue-900/60 backdrop-blur-sm" onClick={() => setIsAdminOpen(false)} />
            <motion.div 
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              className="bg-white w-full max-w-2xl rounded-3xl overflow-hidden shadow-2xl relative z-10"
            >
              <div className="bg-blue-600 p-6 text-white flex justify-between items-center">
                <h2 className="text-xl font-bold flex items-center gap-2"><Settings /> {t.adminTitle}</h2>
                <button onClick={() => setIsAdminOpen(false)} className="hover:rotate-90 transition-transform"><X /></button>
              </div>

              <div className="p-8">
                {!isAuthorized ? (
                  <div className="space-y-4">
                    <label className="block font-semibold text-gray-700">{t.adminPass}</label>
                    <input 
                      type="password" 
                      value={adminPass}
                      onChange={(e) => setAdminPass(e.target.value)}
                      placeholder="admin123"
                      className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500" 
                    />
                    <button 
                      onClick={handleAdminAuth}
                      className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold"
                    >
                      Aceder
                    </button>
                  </div>
                ) : (
                  <div className="space-y-6 max-h-[60vh] overflow-y-auto pr-2">
                    <div className="flex justify-between items-center">
                      <h3 className="font-bold text-gray-800">Gerir Slides</h3>
                      <button 
                        onClick={() => handleSaveSlides([...slides, { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: "https://images.unsplash.com/photo-1517646287270-a5a9ca602e5c?auto=format&fit=crop&q=80&w=800", tag: "Novidade" }])}
                        className="text-blue-600 flex items-center gap-1 font-semibold"
                      >
                        <Plus size={18} /> Adicionar
                      </button>
                    </div>

                    {slides.map((slide, idx) => (
                      <div key={slide.id} className="p-4 border rounded-2xl space-y-3 bg-gray-50">
                        <div className="flex justify-between items-start">
                          <span className="text-xs font-bold text-gray-400">Slide #{idx + 1}</span>
                          <button onClick={() => handleSaveSlides(slides.filter(s => s.id !== slide.id))} className="text-red-500"><Trash2 size={16} /></button>
                        </div>
                        <input 
                          type="text" 
                          placeholder="Título" 
                          value={slide.title}
                          onChange={(e) => {
                            const newSlides = [...slides];
                            newSlides[idx].title = e.target.value;
                            handleSaveSlides(newSlides);
                          }}
                          className="w-full p-2 border rounded-lg text-sm" 
                        />
                        <input 
                          type="text" 
                          placeholder="Descrição" 
                          value={slide.description}
                          onChange={(e) => {
                            const newSlides = [...slides];
                            newSlides[idx].description = e.target.value;
                            handleSaveSlides(newSlides);
                          }}
                          className="w-full p-2 border rounded-lg text-sm" 
                        />
                        <div className="grid grid-cols-2 gap-2">
                           <input 
                            type="text" 
                            placeholder="Tag (ex: Luxo)" 
                            value={slide.tag}
                            onChange={(e) => {
                              const newSlides = [...slides];
                              newSlides[idx].tag = e.target.value;
                              handleSaveSlides(newSlides);
                            }}
                            className="p-2 border rounded-lg text-sm" 
                          />
                           <input 
                            type="text" 
                            placeholder="URL da Imagem" 
                            value={slide.image}
                            onChange={(e) => {
                              const newSlides = [...slides];
                              newSlides[idx].image = e.target.value;
                              handleSaveSlides(newSlides);
                            }}
                            className="p-2 border rounded-lg text-sm" 
                          />
                        </div>
                      </div>
                    ))}

                    <button 
                      onClick={() => setIsAdminOpen(false)}
                      className="w-full bg-green-600 text-white py-4 rounded-xl font-bold flex items-center justify-center gap-2"
                    >
                      <Save size={20} /> Fechar e Aplicar
                    </button>
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);

