                      <div key={s.id} className="p-4 border rounded-2xl bg-slate-50 space-y-4">
                        <div className="flex justify-between items-center text-[10px] font-bold uppercase text-slate-400"><span>Slide {idx + 1}</span><button onClick={() => handleSaveSlides(slides.filter(slide => slide.id !== s.id))} className="text-red-400"><Trash2 size={16}/></button></div>
                        <input value={s.title} onChange={(e) => { const n = [...slides]; n[idx].title = e.target.value; handleSaveSlides(n); }} className="w-full p-2 border rounded-lg" placeholder="Título" />
                        <textarea value={s.description} onChange={(e) => { const n = [...slides]; n[idx].description = e.target.value; handleSaveSlides(n); }} className="w-full p-2 border rounded-lg" placeholder="Descrição" />
                        <input value={s.image} onChange={(e) => { const n = [...slides]; n[idx].image = e.target.value; handleSaveSlides(n); }} className="w-full p-2 border rounded-lg text-xs font-mono" placeholder="Image URL" />
                      </div>
                    ))}
                    <button onClick={() => setIsAdminOpen(false)} className="w-full bg-[#00ADEF] text-white py-4 rounded-xl font-bold uppercase tracking-widest"><Save size={18} className="inline mr-2" /> {t.save}</button>
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

