                           <input value={s.image} onChange={(e) => { const n = [...slides]; n[idx].image = e.target.value; handleSaveSlides(n); }} className="p-5 bg-black border border-white/5 rounded-2xl font-mono text-[10px] text-white/20" placeholder="URL da Imagem" />
