    const interval = setInterval(() => setCurrentSlide(p => (p + 1) % slides.length), 9000);
    return () => clearInterval(interval);
  }, [slides]);

  useEffect(() => {
    localStorage.setItem('rosimeire_slides_v8', JSON.stringify(slides));
  }, [slides]);

  useEffect(() => {
    localStorage.setItem('rosimeire_notices_v8', JSON.stringify(notices));
  }, [notices]);

  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0].image, tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };

  const removeSlide = (id: string) => {
    if (slides.length <= 1) return;
    setSlides(slides.filter(s => s.id !== id));
    if (currentSlide >= slides.length - 1) setCurrentSlide(0);
  };

  const updateSlide = (id: string, field: keyof Slide, value: string) => {
    setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));
  };

  const addNotice = () => {
    const newNotice: Notice = { id: Date.now().toString(), text: "Novo aviso...", active: true };
    setNotices([...notices, newNotice]);
  };

  const removeNotice = (id: string) => {
    setNotices(notices.filter(n => n.id !== id));
  };

  const updateNotice = (id: string, text: string) => {
    setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  };

  const toggleNotice = (id: string) => {
    setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));
  };

  return (
