                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    <div className="space-y-4">
                      <label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.email}</label>
                      <input required type="email" className="w-full bg-transparent border-b border-white/10 py-6 text-2xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.phone}</label>
                      <input required type="tel" className="w-full bg-transparent border-b border-white/10 py-6 text-2xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.message}</label>
                    <textarea required rows={3} className="w-full bg-transparent border-b border-white/10 py-6 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                  </div>
                  <button disabled={formStatus !== 'idle'} className={`w-full py-10 rounded-sm font-bold text-[10px] uppercase tracking-[0.6em] transition-all ${formStatus === 'success' ? 'bg-green-900 text-white' : 'btn-serenity'}`}>
                    {formStatus === 'idle' ? t.send : formStatus === 'sending' ? "..." : t.success}
                  </button>
                </form>
              </motion.div>
            </div>
          </div>
        </section>
      </main>

      <GlassDivider />

      {/* Footer Discreto */}
      <footer className="py-20 bg-[#040911]">
        <div className="container mx-auto px-8 md:px-16 flex flex-col md:flex-row justify-between items-center gap-12">
          <div className="text-center md:text-left">
            <h5 className="text-white font-light tracking-[0.4em] text-sm mb-4">ROSIMEIRE LUXURY</h5>
            <p className="text-[9px] font-bold tracking-[0.5em] text-white/20 uppercase">{t.footerNote}</p>
          </div>
          <div className="flex gap-12 text-[10px] font-bold uppercase tracking-[0.3em] text-white/30">
            <a href="#" className="hover:text-[#f8c8c4] transition-colors">Instagram</a>
            <a href="#" className="hover:text-[#f8c8c4] transition-colors">Private</a>
            <a href="#" className="hover:text-[#f8c8c4] transition-colors">Algarve</a>
          </div>
          <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase">© 2025. Pure Legacy.</p>
        </div>
      </footer>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);

