              {activeAdminTab === 'notices' && (
                <div className="space-y-12 max-w-4xl mx-auto">
                  {notices.map((n) => (
                    <div key={n.id} className="crystal-card p-10 flex flex-col md:flex-row gap-8 items-center justify-between">
