                      <div className="flex items-center gap-8">
                        <button 
                          onClick={() => toggleNotice(n.id)}
                          className={`p-4 rounded border transition-all ${n.active ? 'border-[#f8c8c4] text-[#f8c8c4]' : 'border-white/10 text-white/20'}`}
                          title={n.active ? "Ativado" : "Desativado"}
