                  <button onClick={addNotice} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
                    <Plus size={20} /> {t.adminNotices}
