              <div className="mt-24 pt-12 border-t border-white/5 flex justify-center">
                 <button onClick={() => setIsAdminOpen(false)} className="btn-serenity px-24 flex items-center gap-4">
                   <Save size={14} /> Salvar e Finalizar
                 </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Menu Mobile */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.div initial={{ opacity: 0, y: -20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }}
            className="fixed inset-0 z-[90] bg-[#081221] flex flex-col p-16 pt-40 gap-12 text-4xl font-light tracking-tighter"
          >
            <a href="#home" onClick={() => setIsMenuOpen(false)}>{t.navHome}</a>
            <a href="#services" onClick={() => setIsMenuOpen(false)}>{t.navServices}</a>
            <a href="#reviews" onClick={() => setIsMenuOpen(false)}>{t.navReviews}</a>
            <a href="#quote" onClick={() => setIsMenuOpen(false)} className="text-[#f8c8c4]">{t.navContact}</a>
            <div className="mt-auto border-t border-white/10 pt-12 flex flex-col gap-8">
