                <a key={idx} href={`#${item.toLowerCase()}`} className="hover:text-white transition-all hover:tracking-[0.5em]">{t[`nav${item}` as keyof typeof t]}</a>
              ))}
            </div>
          </nav>
        </div>
      </header>

      {/* Painel Administrativo */}
