  { id: '1', text: "Nova especialidade de Limpeza Técnica de Cristais agora disponível.", active: true }
];

const REVIEWS = [
  { 
    id: '1', 
    text: "A discrição e o detalhe são de outro nível. Tornaram a nossa villa um refúgio impecável.", 
    author: "Elena Martens", 
    location: "Quinta do Lago" 
  },
  { 
