import React from 'react';
import { motion } from 'framer-motion';
import { Settings, Trash2, Plus, Save, Bell, X } from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  activeTab: 'slides' | 'notices';
  setActiveTab: (tab: 'slides' | 'notices') => void;
  t: any;
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, notices, setNotices, activeTab, setActiveTab, t
}) => {
  if (!isOpen) return null;

  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0].image, tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };

  const removeSlide = (id: string) => {
    if (slides.length <= 1) return;
    setSlides(slides.filter(s => s.id !== id));
  };

  const updateSlide = (id: string, field: keyof Slide, value: string) => {
    setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));
  };

  const addNotice = () => {
    const newNotice: Notice = { id: Date.now().toString(), text: "Novo aviso...", active: true };
    setNotices([...notices, newNotice]);
  };

  const removeNotice = (id: string) => {
    setNotices(notices.filter(n => n.id !== id));
  };

  const updateNotice = (id: string, text: string) => {
    setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  };

  const toggleNotice = (id: string) => {
    setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));
  };

  return (
    <motion.div 
      initial={{ opacity: 0, x: '100%' }} 
      animate={{ opacity: 1, x: 0 }} 
      exit={{ opacity: 0, x: '100%' }}
      className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto"
    >
      <div className="container mx-auto px-8 md:px-32 py-24">
        <div className="flex justify-between items-center mb-24">
          <div className="flex items-center gap-8">
            <h2 className="heading-serif text-4xl md:text-7xl">{t.adminTitle}</h2>
