import React from 'react';
import { motion } from 'framer-motion';
import { Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon } from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface Review {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar?: string;
  initials: string;
  color: string;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  reviews: Review[];
  setReviews: (reviews: Review[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: 'slides' | 'notices' | 'reviews';
  setActiveTab: (tab: 'slides' | 'notices' | 'reviews') => void;
  t: any;
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, notices, setNotices, reviews, setReviews, 
  googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t
}) => {
  if (!isOpen) return null;

  // Handlers para Slides
  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0]?.image || "", tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };
  const removeSlide = (id: string) => slides.length > 1 && setSlides(slides.filter(s => s.id !== id));
  const updateSlide = (id: string, field: keyof Slide, value: string) => setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));

  // Handlers para Avisos
  const addNotice = () => {
    const newNotice: Notice = { id: Date.now().toString(), text: "Novo aviso...", active: true };
    setNotices([...notices, newNotice]);
  };
  const removeNotice = (id: string) => setNotices(notices.filter(n => n.id !== id));
  const updateNotice = (id: string, text: string) => setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  const toggleNotice = (id: string) => setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));

  // Handlers para Depoimentos
  const addReview = () => {
    const newReview: Review = { 
      id: Date.now().toString(), 
      author: "Novo Autor", 
      text: "Conteúdo do depoimento...", 
      time: "Agora mesmo", 
      initials: "NA", 
      color: "#f8c8c4" 
    };
    setReviews([...reviews, newReview]);
  };
  const removeReview = (id: string) => setReviews(reviews.filter(r => r.id !== id));
  const updateReview = (id: string, field: keyof Review, value: string) => setReviews(reviews.map(r => r.id === id ? { ...r, [field]: value } : r));

  return (
    <motion.div 
      initial={{ opacity: 0, x: '100%' }} 
      animate={{ opacity: 1, x: 0 }} 
      exit={{ opacity: 0, x: '100%' }}
      className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto"
    >
      <div className="container mx-auto px-8 md:px-32 py-24">
        <div className="flex justify-between items-center mb-24">
          <div className="flex items-center gap-8">
            <h2 className="heading-serif text-4xl md:text-7xl">{t.adminTitle}</h2>
            <Settings className="text-[#f8c8c4]/30 animate-spin-slow" size={40} />
          </div>
          <div className="flex gap-4">
            <button onClick={onLogout} className="text-[10px] font-bold tracking-widest uppercase text-white/40 hover:text-white transition-colors mr-8">Sair da Conta</button>
            <button onClick={onClose} className="btn-serenity">{t.logout}</button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-16 border-b border-white/5 mb-16">
          <button 
            onClick={() => setActiveTab('slides')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'slides' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminSlides}
          </button>
          <button 
            onClick={() => setActiveTab('notices')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'notices' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminNotices}
          </button>
          <button 
            onClick={() => setActiveTab('reviews')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'reviews' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminReviews}
          </button>
        </div>

        {/* Content */}
        {activeTab === 'slides' && (
          <div className="space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {slides.map((s) => (
                <div key={s.id} className="crystal-card p-12 rounded-sm space-y-8 relative">
                  <button onClick={() => removeSlide(s.id)} className="absolute top-8 right-8 text-red-500/40 hover:text-red-500 transition-colors"><Trash2 size={20} /></button>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Imagem URL</label>
                    <input value={s.image} onChange={(e) => updateSlide(s.id, 'image', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none focus:border-[#f8c8c4]/50" />
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Tag</label>
                      <input value={s.tag} onChange={(e) => updateSlide(s.id, 'tag', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold tracking-widest rounded outline-none focus:border-[#f8c8c4]/50" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Título</label>
                      <input value={s.title} onChange={(e) => updateSlide(s.id, 'title', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none focus:border-[#f8c8c4]/50" />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Descrição</label>
                    <textarea value={s.description} onChange={(e) => updateSlide(s.id, 'description', e.target.value)} rows={3} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none focus:border-[#f8c8c4]/50" />
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addSlide} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> {t.adminSlides}
            </button>
          </div>
        )}

        {activeTab === 'notices' && (
          <div className="space-y-12 max-w-4xl mx-auto">
            {notices.map((n) => (
              <div key={n.id} className="crystal-card p-10 flex flex-col md:flex-row gap-8 items-center justify-between">
                <div className="flex-1 w-full space-y-4">
                  <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Texto do Aviso</label>
                  <input value={n.text} onChange={(e) => updateNotice(n.id, e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-sm font-bold tracking-widest rounded outline-none focus:border-[#f8c8c4]/50" />
                </div>
                <div className="flex items-center gap-8">
                  <button onClick={() => toggleNotice(n.id)} className={`p-4 rounded border transition-all ${n.active ? 'border-[#f8c8c4] text-[#f8c8c4]' : 'border-white/10 text-white/20'}`} title={n.active ? "Ativado" : "Desativado"}><Bell size={18} /></button>
                  <button onClick={() => removeNotice(n.id)} className="p-4 text-red-500/40 hover:text-red-500 transition-colors"><Trash2 size={20} /></button>
                </div>
              </div>
            ))}
            <button onClick={addNotice} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> {t.adminNotices}
            </button>
          </div>
        )}

        {activeTab === 'reviews' && (
          <div className="space-y-16">
            {/* Google Maps Link Management */}
            <div className="crystal-card p-10 border-[#f8c8c4]/20 border">
              <div className="flex items-center gap-4 mb-8">
                <LinkIcon size={20} className="text-[#f8c8c4]" />
                <h3 className="text-xl font-light uppercase tracking-widest">Link do Google Maps</h3>
              </div>
              <div className="space-y-4">
                <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">URL de Referência para Reviews</label>
                <input 
                  value={googleMapsLink} 
                  onChange={(e) => setGoogleMapsLink(e.target.value)} 
                  className="w-full bg-white/5 border border-white/10 p-4 text-sm font-light rounded outline-none focus:border-[#f8c8c4]/50" 
                  placeholder="Cole aqui o link do Google Maps..."
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {reviews.map((r) => (
                <div key={r.id} className="crystal-card p-12 rounded-sm space-y-8 relative">
                  <button onClick={() => removeReview(r.id)} className="absolute top-8 right-8 text-red-500/40 hover:text-red-500 transition-colors"><Trash2 size={20} /></button>
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Autor</label>
                      <input value={r.author} onChange={(e) => updateReview(r.id, 'author', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Tempo</label>
                      <input value={r.time} onChange={(e) => updateReview(r.id, 'time', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Iniciais (Avatar)</label>
                      <input value={r.initials} onChange={(e) => updateReview(r.id, 'initials', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Avatar URL (Opcional)</label>
                      <input value={r.avatar || ""} onChange={(e) => updateReview(r.id, 'avatar', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Texto do Depoimento</label>
                    <textarea value={r.text} onChange={(e) => updateReview(r.id, 'text', e.target.value)} rows={4} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addReview} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> Adicionar Depoimento
            </button>
          </div>
        )}

        <div className="mt-24 pt-12 border-t border-white/5 flex justify-center">
          <button onClick={onClose} className="btn-serenity px-24 flex items-center gap-4">
            <Save size={14} /> Salvar e Finalizar
          </button>
        </div>
      </div>
    </motion.div>
  );
};

