const App = () => {
  const [lang, setLang] = useState<Language>('PT');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isLoginOpen, setIsLoginOpen] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeAdminTab, setActiveAdminTab] = useState<'slides' | 'notices' | 'reviews' | 'partners'>('slides');

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);

  const [slides, setSlides] = useState<Slide[]>(() => {
    const saved = localStorage.getItem('rosimeire_slides_v10');
    return saved ? JSON.parse(saved) : DEFAULT_SLIDES;
  });

  const [notices, setNotices] = useState<Notice[]>(() => {
    const saved = localStorage.getItem('rosimeire_notices_v10');
    return saved ? JSON.parse(saved) : DEFAULT_NOTICES;
  });

  const [reviews, setReviews] = useState<Review[]>(() => {
    const saved = localStorage.getItem('rosimeire_reviews_v10');
    return saved ? JSON.parse(saved) : DEFAULT_REVIEWS;
  });

  const [partners, setPartners] = useState<Partner[]>(() => {
    const saved = localStorage.getItem('rosimeire_partners_v10');
    return saved ? JSON.parse(saved) : DEFAULT_PARTNERS;
  });

  const [googleMapsLink, setGoogleMapsLink] = useState<string>(() => {
    const saved = localStorage.getItem('rosimeire_maps_v10');
    return saved || INITIAL_GOOGLE_MAPS_LINK;
  });

  const [currentSlide, setCurrentSlide] = useState(0);
  const [formStatus, setFormStatus] = useState<'idle' | 'sending' | 'success'>('idle');
  const t = translations[lang];

  useEffect(() => {
    const interval = setInterval(() => setCurrentSlide(p => (p + 1) % slides.length), 9000);
    return () => clearInterval(interval);
  }, [slides]);

  useEffect(() => {
    localStorage.setItem('rosimeire_slides_v10', JSON.stringify(slides));
    localStorage.setItem('rosimeire_notices_v10', JSON.stringify(notices));
    localStorage.setItem('rosimeire_reviews_v10', JSON.stringify(reviews));
    localStorage.setItem('rosimeire_partners_v10', JSON.stringify(partners));
    localStorage.setItem('rosimeire_maps_v10', googleMapsLink);
  }, [slides, notices, reviews, partners, googleMapsLink]);

  const handleAdminAccess = () => {
    if (isAuthenticated) setIsAdminOpen(true);
    else setIsLoginOpen(true);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'admin' && password === 'rosimeire2025') {
      setIsAuthenticated(true);
      setIsLoginOpen(false);
      setIsAdminOpen(true);
      setLoginError(false);
    } else setLoginError(true);
  };

  const ReviewCard = ({ r, link }: { r: Review, link: string }) => (
    <a 
      href={link}
      target="_blank"
      rel="noopener noreferrer"
      className="crystal-card p-6 rounded-sm group flex flex-col justify-between h-[230px] w-[300px] md:w-[380px] flex-shrink-0 mx-4 cursor-pointer hover:border-[#f8c8c4]/40 transition-all block"
    >
      <div>
        <div className="flex items-center gap-4 mb-4">
          <div className="relative w-10 h-10 rounded-full border border-white/5 shadow-md p-0.5">
            {r.avatar ? (
              <img src={r.avatar} alt={r.author} className="w-full h-full rounded-full object-cover" />
            ) : (
              <div className="w-full h-full rounded-full flex items-center justify-center text-white font-black text-[10px]" style={{ backgroundColor: r.color }}>{r.initials}</div>
            )}
            <div className="absolute -bottom-1 -right-1 w-4 h-4 bg-white rounded-full flex items-center justify-center shadow-md overflow-hidden p-0.5">
               <svg viewBox="0 0 24 24" className="w-full h-full"><path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/><path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/><path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/><path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/></svg>
            </div>
          </div>
          <div>
            <h4 className="text-white/80 font-bold tracking-widest text-[9px] uppercase">{r.author}</h4>
            <p className="text-white/10 text-[7px] font-bold uppercase tracking-[0.2em] mt-0.5">{r.time}</p>
          </div>
        </div>
        <div className="flex items-center gap-2 mb-3">
          <div className="flex gap-0.5 text-[#f8c8c4]/60">{[...Array(5)].map((_, idx) => <Star key={idx} size={10} fill="currentColor" />)}</div>
          <CheckCircle2 size={10} className="text-[#3b82f6]/40" />
        </div>
        <p className="text-white/30 text-[11px] font-light leading-snug italic group-hover:text-white/50 transition-colors line-clamp-3">"{r.text}"</p>
      </div>
      <div className="flex justify-end opacity-0 group-hover:opacity-40 transition-opacity">
        <ExternalLink size={10} className="text-[#f8c8c4]" />
      </div>
      <div className="h-[1px] w-0 bg-[#f8c8c4]/20 group-hover:w-full transition-all duration-1000 mt-4"></div>
    </a>
  );

  const PartnerCard = ({ p }: { p: Partner }) => (
    <a 
      href={p.url}
      target="_blank"
      rel="noopener noreferrer"
      className="crystal-card flex items-center justify-center h-[180px] w-[180px] flex-shrink-0 mx-6 p-8 group relative overflow-hidden"
    >
      <img 
        src={p.logo} 
        alt={p.name} 
        className="w-full h-full object-contain filter grayscale invert brightness-150 contrast-50 group-hover:contrast-100 group-hover:brightness-100 transition-all duration-700 opacity-20 group-hover:opacity-60" 
        style={{ filter: 'grayscale(1) brightness(1.2) sepia(0.2) hue-rotate(320deg) saturate(0.5)' }}
      />
      <div className="absolute inset-0 bg-[#f8c8c4]/5 opacity-0 group-hover:opacity-100 transition-opacity" />
    </a>
  );

  return (
    <div className="min-h-screen selection:bg-[#f8c8c4] selection:text-[#081221]">

      <div className="fixed top-0 w-full z-[100] flex flex-col">
        <AnimatePresence>
          {notices.filter(n => n.active).map((notice) => (
            <motion.div 
              key={notice.id}
              initial={{ height: 0, opacity: 0 }} 
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              className="bg-[#f8c8c4] text-[#081221] py-2 px-8 flex justify-center items-center gap-4 relative"
            >
              <Bell size={12} />
              <span className="text-[10px] font-black tracking-[0.3em] uppercase">{notice.text}</span>
            </motion.div>
          ))}
        </AnimatePresence>

        <header className="glass-nav transition-all border-b border-white/5">
          <div className="px-8 md:px-16 py-4 flex justify-between items-center">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex items-center gap-6">
              <span className="text-xl md:text-2xl font-light tracking-[0.3em] text-white uppercase">ROSIMEIRE</span>
              <span className="w-8 h-[1px] bg-[#f8c8c4]/30 hidden md:block"></span>
              <span className="text-[8px] font-bold tracking-[0.5em] text-[#f8c8c4] uppercase hidden md:block">Est. 2012</span>
            </motion.div>
            <div className="hidden lg:flex items-center gap-8">
              <div className="flex gap-4">
                {['PT', 'EN', 'ES'].map(l => (
                  <button key={l} onClick={() => setLang(l as Language)} className={`text-[8px] font-black tracking-widest ${lang === l ? 'text-[#f8c8c4]' : 'text-white/10 hover:text-white/40'}`}>{l}</button>
                ))}
              </div>
              <div className="w-[1px] h-3 bg-white/5"></div>
              <a href="#quote" className="btn-serenity !py-2 !px-6">{t.navContact}</a>
              <div className="w-[1px] h-3 bg-white/5"></div>
              <a href="https://sir.rosimeire.pt" target="_blank" rel="noopener noreferrer" className="flex items-center gap-2 text-[8px] font-bold tracking-[0.3em] text-[#f8c8c4]/60 hover:text-[#f8c8c4] transition-all group uppercase">
                SIR <ExternalLink size={10} className="group-hover:translate-x-1 transition-transform" />
              </a>
              <button onClick={handleAdminAccess} className={`transition-colors ${isAuthenticated ? 'text-[#f8c8c4]' : 'text-white/20 hover:text-[#f8c8c4]'}`}>
                <Settings size={14} />
              </button>
            </div>
            <button className="lg:hidden text-white/60" onClick={() => setIsMenuOpen(!isMenuOpen)}>
              {isMenuOpen ? <X size={28} /> : <Menu size={28} />}
            </button>
          </div>
          <div className="hidden lg:block border-t border-white/5">
            <nav className="container mx-auto flex justify-center py-4">
              <div className="flex gap-16 text-[10px] font-bold uppercase tracking-[0.4em] text-white/40">
                {['Home', 'Services', 'Reviews'].map((item, idx) => (
                  <a key={idx} href={`#${item.toLowerCase()}`} className="hover:text-white transition-all hover:tracking-[0.5em]">{t[`nav${item}` as keyof typeof t]}</a>
                ))}
              </div>
            </nav>
          </div>
        </header>
      </div>

      <AnimatePresence>
        {isLoginOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1100] flex items-center justify-center bg-[#081221]/80 backdrop-blur-md px-8">
            <motion.div initial={{ scale: 0.9, y: 20 }} animate={{ scale: 1, y: 0 }} className="crystal-card w-full max-w-md p-12 relative">
              <button onClick={() => setIsLoginOpen(false)} className="absolute top-8 right-8 text-white/20 hover:text-white"><X size={20}/></button>
              <div className="text-center mb-8">
                <Lock className="mx-auto text-[#f8c8c4] mb-6" size={32} />
                <h3 className="heading-serif text-3xl">Acesso Restrito</h3>
                <p className="text-[10px] font-bold tracking-[0.3em] uppercase text-white/30 mt-4">Somente para Gestão</p>
              </div>
              <form onSubmit={handleLogin} className="space-y-8">
                <div className="space-y-2">
                  <label className="text-[9px] font-bold uppercase tracking-[0.3em] text-white/40 flex items-center gap-2"><User size={10}/> Utilizador</label>
                  <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-sm rounded outline-none focus:border-[#f8c8c4]/50 transition-all" required />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-bold uppercase tracking-[0.3em] text-white/40 flex items-center gap-2"><Lock size={10}/> Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-sm rounded outline-none focus:border-[#f8c8c4]/50 transition-all" required />
                </div>
                {loginError && <p className="text-[10px] text-red-400 font-bold uppercase tracking-widest text-center italic">Credenciais Inválidas</p>}
                <button type="submit" className="w-full btn-serenity py-4">Entrar</button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isAdminOpen && (
          <AdminPanel 
            isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
            slides={slides} setSlides={setSlides} notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews}
            partners={partners} setPartners={setPartners}
            googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink} activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={t}
          />
        )}
      </AnimatePresence>

      <main>
        <section id="home" className="h-screen relative flex items-center overflow-hidden pt-32 lg:pt-48">
          <AnimatePresence mode="wait">
            <motion.div key={currentSlide} initial={{ opacity: 0, scale: 1.05 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} transition={{ duration: 2 }} className="absolute inset-0">
               <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${slides[currentSlide]?.image})` }} />
               <div className="absolute inset-0 bg-gradient-to-r from-[#081221] via-[#081221]/40 to-transparent" />
            </motion.div>
          </AnimatePresence>
          <div className="container mx-auto px-8 md:px-16 relative z-10">
            <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }}>
              <span className="tagline mb-10 block">{slides[currentSlide]?.tag} — {t.heroSubtitle}</span>
              <h1 className="heading-serif text-6xl md:text-[8rem] text-white mb-12">
                {slides[currentSlide]?.title.split(' ')[0]}<br/>
                <span className="italic font-light opacity-60 text-[#f8c8c4]">{slides[currentSlide]?.title.split(' ').slice(1).join(' ')}</span>
              </h1>
              <p className="text-lg md:text-xl font-light text-white/50 max-w-xl leading-relaxed mb-16">{slides[currentSlide]?.description}</p>
              <div className="flex flex-col sm:flex-row gap-10 items-center">
                <a href="#quote" className="btn-serenity w-full sm:w-auto text-center">{t.navContact}</a>
                <a href="#services" className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/40 hover:text-[#f8c8c4] flex items-center gap-4 group">
                  EXPLORAR SERVIÇOS <ArrowRight size={14} className="group-hover:translate-x-2 transition-transform"/>
                </a>
              </div>
            </motion.div>
          </div>
        </section>

        <GlassDivider />

        <section id="services" className="py-40 md:py-64 relative">
          <div className="container mx-auto px-8 md:px-16">
            <div className="flex flex-col md:flex-row justify-between items-start mb-32 gap-16">
               <div className="max-w-3xl">
                 <span className="tagline mb-8 block">{t.servicesTitle}</span>
                 <h2 className="heading-serif text-5xl md:text-8xl text-white">{t.servicesSubtitle}</h2>
               </div>
               <div className="space-y-8 max-w-xs pt-4">
                 <p className="text-white/30 text-xs font-medium leading-loose tracking-wide">Cada espaço tem sua própria alma. Nossa curadoria garante que ela brilhe através de um cuidado invisível e sofisticado.</p>
                 <div className="flex gap-4 text-[#f8c8c4]/40"><Shield size={20}/><Wind size={20}/><Sparkle size={20}/></div>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
              {[
                { title: t.alTitle, desc: t.alDesc, icon: <Home size={28}/> },
                { title: t.postTitle, desc: t.postDesc, icon: <Paintbrush size={28}/> },
                { title: t.privateTitle, desc: t.privateDesc, icon: <Gem size={28}/> },
                { title: t.otherTitle, desc: t.otherDesc, icon: <Building2 size={28}/> }
              ].map((s, idx) => (
                <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: idx * 0.1 }} key={idx} className="crystal-card p-12 rounded-sm group flex flex-col justify-between h-[450px]">
                   <div>
                     <div className="text-[#f8c8c4]/60 mb-12 group-hover:scale-110 transition-transform duration-700">{s.icon}</div>
                     <h3 className="text-2xl font-light text-white mb-8 tracking-tighter uppercase">{s.title}</h3>
                     <p className="text-white/40 text-sm font-light leading-relaxed group-hover:text-white/60 transition-colors">{s.desc}</p>
                   </div>
                   <div className="h-[1px] w-0 bg-[#f8c8c4]/40 group-hover:w-full transition-all duration-1000"></div>
                </motion.div>
              ))}
            </div>
          </div>
        </section>

        <GlassDivider />

        <section id="reviews" className="py-40 bg-[#060d18] relative overflow-hidden">
          <div className="container mx-auto px-8 md:px-16">
            <div className="text-center mb-24">
              <span className="tagline mb-8 block">{t.reviewsTitle}</span>
              <h2 className="heading-serif text-4xl md:text-6xl text-white">Confiança em<br/><span className="italic opacity-60 text-[#f8c8c4]">cada detalhe</span></h2>
            </div>
          </div>

          <div className="relative w-full overflow-hidden py-4 flex">
            <motion.div 
              className="flex whitespace-nowrap"
              animate={{ x: [0, "-50%"] }}
              transition={{ ease: "linear", duration: 180, repeat: Infinity }}
              whileHover={{ animationPlayState: "paused" }} 
            >
              <div className="flex">
                {reviews.map((r, i) => <ReviewCard r={r} link={googleMapsLink} key={`r1-${r.id}`} />)}
              </div>
              <div className="flex">
                {reviews.map((r, i) => <ReviewCard r={r} link={googleMapsLink} key={`r2-${r.id}`} />)}
              </div>
            </motion.div>
          </div>
        </section>

        <GlassDivider />

        {/* Parceiros de Prestígio */}
        <section id="partners" className="py-40 bg-[#081221] relative overflow-hidden">
          <div className="container mx-auto px-8 md:px-16 mb-24 text-center">
            <span className="tagline mb-8 block">{t.partnersTitle}</span>
          </div>

          <div className="relative w-full overflow-hidden py-4 flex">
            <motion.div 
              className="flex whitespace-nowrap"
              animate={{ x: [0, "-50%"] }}
              transition={{ ease: "linear", duration: 120, repeat: Infinity }}
              whileHover={{ animationPlayState: "paused" }} 
            >
              <div className="flex">
                {partners.map((p) => <PartnerCard p={p} key={`p1-${p.id}`} />)}
              </div>
              <div className="flex">
                {partners.map((p) => <PartnerCard p={p} key={`p2-${p.id}`} />)}
              </div>
            </motion.div>
          </div>
        </section>

        <GlassDivider />

        <section id="quote" className="py-40 md:py-64">
          <div className="container mx-auto px-8 md:px-16">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-32 items-center">
              <div>
                <span className="tagline mb-10 block">{t.quoteTitle}</span>
                <h2 className="heading-serif text-6xl md:text-9xl text-white mb-16 tracking-tighter">Private<br/><span className="text-[#f8c8c4]/60">Concierge</span></h2>
                <div className="space-y-12">
                   <div className="flex items-center gap-10 group">
                      <div className="w-12 h-12 border border-white/5 rounded-full flex items-center justify-center text-[#f8c8c4]/40 group-hover:bg-[#f8c8c4] group-hover:text-[#081221] transition-all"><Mail size={20}/></div>
                      <p className="text-xl font-light text-white/40 group-hover:text-white transition-colors">desk@rosimeire.pt</p>
                   </div>
                   <div className="flex items-center gap-10 group">
                      <div className="w-12 h-12 border border-white/5 rounded-full flex items-center justify-center text-[#f8c8c4]/40 group-hover:bg-[#f8c8c4] group-hover:text-[#081221] transition-all"><Phone size={20}/></div>
                      <p className="text-xl font-light text-white/40 group-hover:text-white transition-colors">+351 920 000 000</p>
                   </div>
                </div>
              </div>
              <motion.div initial={{ opacity: 0, x: 20 }} whileInView={{ opacity: 1, x: 0 }} className="crystal-card p-12 md:p-24 rounded-sm">
                <form onSubmit={(e) => { e.preventDefault(); setFormStatus('sending'); setTimeout(() => setFormStatus('success'), 2000); }} className="space-y-12">
                  <div className="space-y-4">
                    <label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.name}</label>
                    <input required type="text" className="w-full bg-transparent border-b border-white/10 py-6 text-2xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                    <div className="space-y-4"><label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.email}</label><input required type="email" className="w-full bg-transparent border-b border-white/10 py-6 text-2xl font-light outline-none focus:border-[#f8c8c4] transition-all" /></div>
                    <div className="space-y-4"><label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.phone}</label><input required type="tel" className="w-full bg-transparent border-b border-white/10 py-6 text-2xl font-light outline-none focus:border-[#f8c8c4] transition-all" /></div>
                  </div>
                  <div className="space-y-4"><label className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/20">{t.message}</label><textarea required rows={3} className="w-full bg-transparent border-b border-white/10 py-6 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" /></div>
                  <button disabled={formStatus !== 'idle'} className={`w-full py-10 rounded-sm font-bold text-[10px] uppercase tracking-[0.6em] transition-all ${formStatus === 'success' ? 'bg-green-900 text-white' : 'btn-serenity'}`}>
                    {formStatus === 'idle' ? t.send : formStatus === 'sending' ? "..." : t.success}
                  </button>
                </form>
              </motion.div>
            </div>
          </div>
        </section>
      </main>

      <GlassDivider />

      <footer className="py-20 bg-[#040911]">
        <div className="container mx-auto px-8 md:px-16 flex flex-col md:flex-row justify-between items-center gap-12">
          <div className="text-center md:text-left">
            <h5 className="text-white font-light tracking-[0.4em] text-sm mb-4 uppercase">ROSIMEIRE LUXURY</h5>
            <p className="text-[9px] font-bold tracking-[0.5em] text-white/20 uppercase">{t.footerNote}</p>
          </div>
          <div className="flex gap-12 text-[10px] font-bold uppercase tracking-[0.3em] text-white/30">
            <a href="#" className="hover:text-[#f8c8c4] transition-colors">Instagram</a>
            <a href="#" className="hover:text-[#f8c8c4] transition-colors">Private</a>
            <a href="#" className="hover:text-[#f8c8c4] transition-colors">Algarve</a>
          </div>
          <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase">© 2025. Pure Legacy.</p>
        </div>
      </footer>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);

import React from 'react';
import { motion } from 'framer-motion';
import { Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon, Briefcase } from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface Review {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar?: string;
  initials: string;
  color: string;
}

interface Partner {
  id: string;
  name: string;
  logo: string;
  url: string;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  reviews: Review[];
  setReviews: (reviews: Review[]) => void;
  partners: Partner[];
  setPartners: (partners: Partner[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: 'slides' | 'notices' | 'reviews' | 'partners';
  setActiveTab: (tab: 'slides' | 'notices' | 'reviews' | 'partners') => void;
  t: any;
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, notices, setNotices, reviews, setReviews, 
  partners, setPartners, googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t
}) => {
  if (!isOpen) return null;

  // Handlers para Slides
  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0]?.image || "", tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };
  const removeSlide = (id: string) => slides.length > 1 && setSlides(slides.filter(s => s.id !== id));
  const updateSlide = (id: string, field: keyof Slide, value: string) => setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));

  // Handlers para Avisos
  const addNotice = () => {
    const newNotice: Notice = { id: Date.now().toString(), text: "Novo aviso...", active: true };
    setNotices([...notices, newNotice]);
  };
  const removeNotice = (id: string) => setNotices(notices.filter(n => n.id !== id));
  const updateNotice = (id: string, text: string) => setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  const toggleNotice = (id: string) => setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));

  // Handlers para Depoimentos
  const addReview = () => {
    const newReview: Review = { 
      id: Date.now().toString(), 
      author: "Novo Autor", 
      text: "Conteúdo do depoimento...", 
      time: "Agora mesmo", 
      initials: "NA", 
      color: "#f8c8c4" 
    };
    setReviews([...reviews, newReview]);
  };
  const removeReview = (id: string) => setReviews(reviews.filter(r => r.id !== id));
  const updateReview = (id: string, field: keyof Review, value: string) => setReviews(reviews.map(r => r.id === id ? { ...r, [field]: value } : r));

  // Handlers para Parceiros
  const addPartner = () => {
    const newPartner: Partner = { 
      id: Date.now().toString(), 
      name: "Novo Parceiro", 
      logo: "", 
      url: "https://" 
    };
    setPartners([...partners, newPartner]);
  };
  const removePartner = (id: string) => setPartners(partners.filter(p => p.id !== id));
  const updatePartner = (id: string, field: keyof Partner, value: string) => setPartners(partners.map(p => p.id === id ? { ...p, [field]: value } : p));

  return (
    <motion.div 
      initial={{ opacity: 0, x: '100%' }} 
      animate={{ opacity: 1, x: 0 }} 
      exit={{ opacity: 0, x: '100%' }}
      className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto"
    >
      <div className="container mx-auto px-8 md:px-32 py-24">
        <div className="flex justify-between items-center mb-24">
          <div className="flex items-center gap-8">
            <h2 className="heading-serif text-4xl md:text-7xl">{t.adminTitle}</h2>
            <Settings className="text-[#f8c8c4]/30 animate-spin-slow" size={40} />
          </div>
          <div className="flex gap-4">
            <button onClick={onLogout} className="text-[10px] font-bold tracking-widest uppercase text-white/40 hover:text-white transition-colors mr-8">Sair da Conta</button>
            <button onClick={onClose} className="btn-serenity">{t.logout}</button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-16 border-b border-white/5 mb-16 overflow-x-auto whitespace-nowrap scrollbar-hide">
          <button 
            onClick={() => setActiveTab('slides')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'slides' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminSlides}
          </button>
          <button 
            onClick={() => setActiveTab('notices')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'notices' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminNotices}
          </button>
          <button 
            onClick={() => setActiveTab('reviews')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'reviews' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminReviews}
          </button>
          <button 
            onClick={() => setActiveTab('partners')}
            className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === 'partners' ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}
          >
            {t.adminPartners}
          </button>
        </div>

        {/* Content */}
        {activeTab === 'slides' && (
          <div className="space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {slides.map((s) => (
                <div key={s.id} className="crystal-card p-12 rounded-sm space-y-8 relative">
                  <button onClick={() => removeSlide(s.id)} className="absolute top-8 right-8 text-red-500/40 hover:text-red-500 transition-colors"><Trash2 size={20} /></button>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Imagem URL</label>
                    <input value={s.image} onChange={(e) => updateSlide(s.id, 'image', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none focus:border-[#f8c8c4]/50" />
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Tag</label>
                      <input value={s.tag} onChange={(e) => updateSlide(s.id, 'tag', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold tracking-widest rounded outline-none focus:border-[#f8c8c4]/50" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Título</label>
                      <input value={s.title} onChange={(e) => updateSlide(s.id, 'title', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none focus:border-[#f8c8c4]/50" />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Descrição</label>
                    <textarea value={s.description} onChange={(e) => updateSlide(s.id, 'description', e.target.value)} rows={3} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none focus:border-[#f8c8c4]/50" />
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addSlide} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> {t.adminSlides}
            </button>
          </div>
        )}

        {activeTab === 'notices' && (
          <div className="space-y-12 max-w-4xl mx-auto">
            {notices.map((n) => (
              <div key={n.id} className="crystal-card p-10 flex flex-col md:flex-row gap-8 items-center justify-between">
                <div className="flex-1 w-full space-y-4">
                  <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Texto do Aviso</label>
