                </div>
                <div className="flex items-center gap-8">
                  <button onClick={() => toggleNotice(n.id)} className={`p-4 rounded border transition-all ${n.active ? 'border-[#f8c8c4] text-[#f8c8c4]' : 'border-white/10 text-white/20'}`} title={n.active ? "Ativado" : "Desativado"}><Bell size={18} /></button>
                  <button onClick={() => removeNotice(n.id)} className="p-4 text-red-500/40 hover:text-red-500 transition-colors"><Trash2 size={20} /></button>
                </div>
              </div>
            ))}
            <button onClick={addNotice} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> {t.adminNotices}
