              </div>
              <div className="space-y-4">
                <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">URL de Referência para Reviews</label>
                <input 
                  value={googleMapsLink} 
                  onChange={(e) => setGoogleMapsLink(e.target.value)} 
                  className="w-full bg-white/5 border border-white/10 p-4 text-sm font-light rounded outline-none focus:border-[#f8c8c4]/50" 
                  placeholder="Cole aqui o link do Google Maps..."
                />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {reviews.map((r) => (
                <div key={r.id} className="crystal-card p-12 rounded-sm space-y-8 relative">
