                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Autor</label>
                      <input value={r.author} onChange={(e) => updateReview(r.id, 'author', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Tempo</label>
                      <input value={r.time} onChange={(e) => updateReview(r.id, 'time', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Iniciais (Avatar)</label>
                      <input value={r.initials} onChange={(e) => updateReview(r.id, 'initials', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none" />
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Avatar URL (Opcional)</label>
                      <input value={r.avatar || ""} onChange={(e) => updateReview(r.id, 'avatar', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Texto do Depoimento</label>
                    <textarea value={r.text} onChange={(e) => updateReview(r.id, 'text', e.target.value)} rows={4} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addReview} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> Adicionar Depoimento
            </button>
          </div>
        )}

        {activeTab === 'partners' && (
          <div className="space-y-16">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              {partners.map((p) => (
                <div key={p.id} className="crystal-card p-12 rounded-sm space-y-8 relative">
                  <button onClick={() => removePartner(p.id)} className="absolute top-8 right-8 text-red-500/40 hover:text-red-500 transition-colors"><Trash2 size={20} /></button>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Nome da Empresa</label>
                    <input value={p.name} onChange={(e) => updatePartner(p.id, 'name', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-bold rounded outline-none" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Logo URL (Formato 1:1 recomendado)</label>
                    <input value={p.logo} onChange={(e) => updatePartner(p.id, 'logo', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-bold tracking-[0.3em] text-white/30 uppercase">Website URL</label>
                    <input value={p.url} onChange={(e) => updatePartner(p.id, 'url', e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-xs font-light rounded outline-none" />
                  </div>
                </div>
              ))}
            </div>
            <button onClick={addPartner} className="w-full py-12 border border-dashed border-white/20 rounded-sm flex items-center justify-center gap-4 text-white/40 hover:border-[#f8c8c4] hover:text-[#f8c8c4] transition-all">
              <Plus size={20} /> Adicionar Parceiro Elite
            </button>
          </div>
        )}

        <div className="mt-24 pt-12 border-t border-white/5 flex justify-center">
          <button onClick={onClose} className="btn-serenity px-24 flex items-center gap-4">
            <Save size={14} /> Salvar e Finalizar
          </button>
        </div>
      </div>
    </motion.div>
  );
};

