        {activeTab === 'partners' && (
          <div className="space-y-12">
            <div className="crystal-card p-8 border-[#f8c8c4]/20 border-dashed">
              <h4 className="text-[10px] font-bold tracking-[0.3em] text-[#f8c8c4] uppercase flex items-center gap-4 mb-4"><Briefcase size={14}/> Guia de Implementação</h4>
              <p className="text-xs text-white/30 italic">Para o efeito de ícone monocromático, utilize logos em **PNG transparente** ou **SVG**. O sistema aplicará a cor da marca automaticamente.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {partners.map(p => (
                <div key={p.id} className="crystal-card p-10 relative space-y-6">
                  <button onClick={() => removePartner(p.id)} className="absolute top-6 right-6 text-red-500/30 hover:text-red-500"><Trash2 size={16}/></button>
