              <><CheckCircle size={16}/> Salvar e Finalizar</>
            )}
            {isSaving && <motion.div initial={{ x: '-100%' }} animate={{ x: '100%' }} transition={{ duration: 1, repeat: Infinity }} className="absolute bottom-0 left-0 h-1 bg-white/40 w-full" />}
          </button>
        </div>
      </div>

      <style>{`
        .admin-input {
          width: 100%;
          background: rgba(255,255,255,0.05);
          border: 1px solid rgba(255,255,255,0.1);
          padding: 1rem;
