          <button 
            onClick={handleFinalize} 
            disabled={isSaving}
            className="btn-serenity px-32 py-8 flex items-center justify-center gap-6 relative overflow-hidden min-w-[400px]"
          >
            {isSaving ? (
              <span className="flex items-center gap-3">
                <motion.div 
