        </div>
        <p className="text-white/30 text-[11px] font-light leading-snug italic group-hover:text-white/50 transition-colors line-clamp-3">"{r.text}"</p>
      </div>
      <div className="flex justify-end opacity-0 group-hover:opacity-40 transition-opacity">
        <ExternalLink size={10} className="text-[#f8c8c4]" />
      </div>
      <div className="h-[1px] w-0 bg-[#f8c8c4]/20 group-hover:w-full transition-all duration-1000 mt-4"></div>
