                  <label className="text-[9px] font-bold uppercase tracking-[0.3em] text-white/40 flex items-center gap-2"><User size={10}/> Utilizador</label>
                  <input type="text" value={username} onChange={(e) => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-sm rounded outline-none focus:border-[#f8c8c4]/50 transition-all" required />
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-bold uppercase tracking-[0.3em] text-white/40 flex items-center gap-2"><Lock size={10}/> Password</label>
                  <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 text-sm rounded outline-none focus:border-[#f8c8c4]/50 transition-all" required />
                </div>
                {loginError && <p className="text-[10px] text-red-400 font-bold uppercase tracking-widest text-center italic">Credenciais Inválidas</p>}
                <button type="submit" className="w-full btn-serenity py-4">Entrar</button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {isAdminOpen && (
          <AdminPanel 
            isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
            slides={slides} setSlides={setSlides} notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews}
            partners={partners} setPartners={setPartners}
            googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink} activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={translations[lang]}
          />
        )}
      </AnimatePresence>

      <main>
        <section id="home" className="h-screen relative flex items-center overflow-hidden pt-32 lg:pt-48">
          <AnimatePresence mode="wait">
            <motion.div key={currentSlide} initial={{ opacity: 0, scale: 1.05 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} transition={{ duration: 2 }} className="absolute inset-0">
               <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${slides[currentSlide]?.image})` }} />
               <div className="absolute inset-0 bg-gradient-to-r from-[#081221] via-[#081221]/40 to-transparent" />
            </motion.div>
          </AnimatePresence>
          <div className="container mx-auto px-8 md:px-16 relative z-10">
            <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }}>
              <span className="tagline mb-10 block">{slides[currentSlide]?.tag} — {t.heroSubtitle}</span>
              <h1 className="heading-serif text-6xl md:text-[8rem] text-white mb-12">
                {slides[currentSlide]?.title.split(' ')[0]}<br/>
                <span className="italic font-light opacity-60 text-[#f8c8c4]">{slides[currentSlide]?.title.split(' ').slice(1).join(' ')}</span>
              </h1>
              <p className="text-lg md:text-xl font-light text-white/50 max-w-xl leading-relaxed mb-16">{slides[currentSlide]?.description}</p>
              <div className="flex flex-col sm:flex-row gap-10 items-center">
                <a href="#quote" className="btn-serenity w-full sm:w-auto text-center">{t.navContact}</a>
                <a href="#services" className="text-[10px] font-bold uppercase tracking-[0.4em] text-white/40 hover:text-[#f8c8c4] flex items-center gap-4 group">
                  EXPLORAR SERVIÇOS <ArrowRight size={14} className="group-hover:translate-x-2 transition-transform"/>
                </a>
              </div>
            </motion.div>
          </div>
        </section>

        <GlassDivider />

        <section id="services" className="py-40 md:py-64 relative">
          <div className="container mx-auto px-8 md:px-16">
            <div className="flex flex-col md:flex-row justify-between items-start mb-32 gap-16">
               <div className="max-w-3xl">
                 <span className="tagline mb-8 block">{t.servicesTitle}</span>
                 <h2 className="heading-serif text-5xl md:text-8xl text-white">{t.servicesSubtitle}</h2>
               </div>
               <div className="space-y-8 max-w-xs pt-4">
                 <p className="text-white/30 text-xs font-medium leading-loose tracking-wide">Cada espaço tem sua própria alma. Nossa curadoria garante que ela brilhe através de um cuidado invisível e sofisticado.</p>
                 <div className="flex gap-4 text-[#f8c8c4]/40"><Shield size={20}/><Wind size={20}/><Sparkle size={20}/></div>
               </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
              {[
                { title: t.alTitle, desc: t.alDesc, icon: <Home size={28}/> },
                { title: t.postTitle, desc: t.postDesc, icon: <Paintbrush size={28}/> },
                { title: t.privateTitle, desc: t.privateDesc, icon: <Gem size={28}/> },
                { title: t.otherTitle, desc: t.otherDesc, icon: <Building2 size={28}/> }
              ].map((s, idx) => (
                <motion.div initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: idx * 0.1 }} key={idx} className="crystal-card p-12 rounded-sm group flex flex-col justify-between h-[450px]">
                   <div>
                     <div className="text-[#f8c8c4]/60 mb-12 group-hover:scale-110 transition-transform duration-700">{s.icon}</div>
                     <h3 className="text-2xl font-light text-white mb-8 tracking-tighter uppercase">{s.title}</h3>
                     <p className="text-white/40 text-sm font-light leading-relaxed group-hover:text-white/60 transition-colors">{s.desc}</p>
                   </div>
                   <div className="h-[1px] w-0 bg-[#f8c8c4]/40 group-hover:w-full transition-all duration-1000"></div>
                </motion.div>
              ))}
            </div>
          </div>
        </section>

        <GlassDivider />

        <section id="reviews" className="py-40 bg-[#060d18] relative overflow-hidden">
          <div className="container mx-auto px-8 md:px-16">
            <div className="text-center mb-24">
              <span className="tagline mb-8 block">{t.reviewsTitle}</span>
              <h2 className="heading-serif text-4xl md:text-6xl text-white">Confiança em<br/><span className="italic opacity-60 text-[#f8c8c4]">cada detalhe</span></h2>
            </div>
          </div>

          <div className="relative w-full overflow-hidden py-4 flex">
            <motion.div 
              className="flex whitespace-nowrap"
              animate={{ x: [0, "-50%"] }}
              transition={{ ease: "linear", duration: 180, repeat: Infinity }}
              whileHover={{ animationPlayState: "paused" }} 
            >
              <div className="flex">
                {reviews.map((r) => <ReviewCard r={r} link={googleMapsLink} key={`r1-${r.id}`} />)}
              </div>
              <div className="flex">
                {reviews.map((r) => <ReviewCard r={r} link={googleMapsLink} key={`r2-${r.id}`} />)}
              </div>
            </motion.div>
          </div>
