      <LogoIcon className="w-full h-full" color="#f8c8c4" windowColor="#f8c8c4" />
    </motion.div>
  </div>
);

const GlassDivider = () => (
  <motion.div 
    initial={{ opacity: 0, scaleX: 0 }}
    whileInView={{ opacity: 1, scaleX: 1 }}
