/**
 * LogoIcon: Reconstrução fiel da logo original baseada na imagem enviada.
 * O design apresenta um "R" sólido com um recorte de casa na base da haste esquerda.
 * No interior da silhueta da casa, encontram-se 3 janelas verticais.
 */
const LogoIcon = ({ className = "w-10 h-10", color = "currentColor" }) => (
  <svg viewBox="0 0 500 580" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
    {/* Estrutura Principal do "R" */}
    <path 
      d="M100 50V400H180V480L260 400H320C400 400 450 340 450 225C450 110 400 50 320 50H100ZM180 130H320C350 130 370 150 370 225C370 300 350 320 320 320H180V130Z" 
      fill={color} 
    />
    {/* Perna Diagonal do "R" */}
    <path 
      d="M260 380L420 550H320L180 400V320L260 380Z" 
      fill={color} 
    />
    {/* Detalhe da Casa (Haste Esquerda inferior) */}
    <path 
      d="M100 400V550H260L180 460V550H100Z" 
      fill={color} 
      opacity="0" /* Este path serve apenas como referência de forma */
    />
    {/* A haste esquerda real com o recorte da casa */}
    <path 
      d="M100 380V550H150V480L180 440L210 480V550H260V380H100Z" 
      fill={color} 
    />
    {/* As 3 Janelas Verticais Conforme Imagem Original */}
    <rect x="115" y="500" width="12" height="35" fill={color} opacity="0.9" />
    <rect x="140" y="500" width="12" height="35" fill={color} opacity="0.9" />
    <rect x="165" y="500" width="12" height="35" fill={color} opacity="0.9" />
  </svg>
