const LogoIcon = ({ className = "w-10 h-10", color = "currentColor" }) => (
  <svg viewBox="0 0 500 580" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
    {/* Silhueta principal do R com recorte da casa e perna diagonal */}
    <path 
      d="M95 40H320C395 40 455 100 455 220C455 340 395 400 320 400H230L390 560H290L175 445V560H145L145 480L175 440L205 480L205 560H265V400H320C345 400 375 375 375 220C375 65 345 120 320 120H175V330H95V40ZM175 220H320C335 220 345 210 345 220C345 230 335 240 320 240H175V220Z" 
      fill={color} 
      opacity="0" /* Path de guia escondido */
    />
    {/* Desenho do Corpo Superior do R */}
    <path 
      d="M100 60V380H320C390 380 440 330 440 220C440 110 390 60 320 60H100ZM180 140H320C340 140 360 160 360 220C360 280 340 300 320 300H180V140Z" 
      fill={color} 
    />
    {/* Perna do R */}
    <path 
      d="M260 380L420 560H320L210 430V380H260Z" 
      fill={color} 
    />
    {/* Haste Esquerda com Recorte da Casa (Fiel à imagem) */}
    <path 
      d="M100 380V560H150V490L180 450L210 490V560H260V380H100Z" 
      fill={color} 
    />
    {/* Janelas da Casa conforme original */}
    <rect x="115" y="510" width="10" height="35" fill={color} />
    <rect x="140" y="510" width="10" height="35" fill={color} />
    <rect x="165" y="510" width="10" height="35" fill={color} />
  </svg>
);

