                <button onClick={handleAdminAccess} className="flex items-center gap-4 text-xs font-bold tracking-[0.4em] text-white/20 uppercase">
                  <Settings size={14} /> GESTÃO
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* --- OVERLAYS --- */}
