          >
            {isSaving ? (
              <span className="flex items-center gap-3">
                <motion.div 
                  animate={{ rotate: 360 }} 
                  transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                >
                  <Settings size={16}/>
                </motion.div>
                Salvando Sessão...
              </span>
            ) : (
              <><CheckCircle size={16}/> Concluir e Sair</>
            )}
            {isSaving && <motion.div initial={{ x: '-100%' }} animate={{ x: '100%' }} transition={{ duration: 1, repeat: Infinity }} className="absolute bottom-0 left-0 h-1 bg-[#f8c8c4] w-full" />}
          </button>
        </div>
      </div>

      <style>{`
        .admin-input {
          width: 100%;
          background: rgba(255,255,255,0.05);
          border: 1px solid rgba(255,255,255,0.1);
          padding: 1rem;
          color: white;
          font-size: 0.8rem;
          border-radius: 2px;
          outline: none;
          transition: border-color 0.3s ease;
        }
        .admin-input:focus { border-color: #f8c8c4; }
        .admin-btn-add {
          width: 100%;
          padding: 2rem;
          border: 1px dashed rgba(255,255,255,0.1);
          color: rgba(255,255,255,0.2);
          text-transform: uppercase;
          font-size: 0.7rem;
          letter-spacing: 0.4em;
          font-weight: bold;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 1rem;
          transition: all 0.3s ease;
        }
        .admin-btn-add:hover { color: #f8c8c4; border-color: #f8c8c4; background: rgba(248,200,196,0.02); }
      `}</style>
    </motion.div>
