export default AdminPanel;

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon, Briefcase, CheckCircle, Image as ImageIcon, RotateCcw, Cloud, Mail, Key, Server, Eye, EyeOff, ShieldCheck, Zap, AlertCircle, Loader2 } from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface SectionImages {
  about: string;
  careers: string;
}

interface EmailConfig {
  recipientEmail: string;
  serviceId: string;
  templateId: string;
  publicKey: string;
  // SMTP
  smtpHost: string;
  smtpPort: string;
  smtpUser: string;
  smtpPass: string;
  smtpSecure: boolean;
  useSmtp: boolean;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface Review {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar?: string;
  initials: string;
  color: string;
}

interface Partner {
  id: string;
  name: string;
  logo: string;
  url: string;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  sectionImages: SectionImages;
  setSectionImages: (imgs: SectionImages) => void;
  emailConfig: EmailConfig;
  setEmailConfig: (config: EmailConfig) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  reviews: Review[];
  setReviews: (reviews: Review[]) => void;
  partners: Partner[];
  setPartners: (partners: Partner[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: 'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email';
  setActiveTab: (tab: 'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email') => void;
  t: any;
  isSyncing: boolean;
  onResetDefaults: () => void;
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, sectionImages, setSectionImages, emailConfig, setEmailConfig, notices, setNotices, reviews, setReviews, 
  partners, setPartners, googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t, isSyncing, onResetDefaults
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [showSmtpPass, setShowSmtpPass] = useState(false);
  const [testStatus, setTestStatus] = useState<'idle' | 'testing' | 'success' | 'error'>('idle');

  if (!isOpen) return null;

  // Handlers
  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0]?.image || "", tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };
  const removeSlide = (id: string) => slides.length > 1 && setSlides(slides.filter(s => s.id !== id));
  const updateSlide = (id: string, field: keyof Slide, value: string) => setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));

  const updateSectionImage = (key: keyof SectionImages, value: string) => {
    setSectionImages({ ...sectionImages, [key]: value });
  };

  const updateEmailConfig = (key: keyof EmailConfig, value: any) => {
    setEmailConfig({ ...emailConfig, [key]: value });
    if (testStatus !== 'idle') setTestStatus('idle');
  };

  const handleTestConnection = async () => {
    if (emailConfig.useSmtp && (!emailConfig.smtpHost || !emailConfig.smtpPort || !emailConfig.smtpUser)) {
      alert("Por favor, preencha os dados do servidor SMTP antes de testar.");
      return;
    }

    setTestStatus('testing');

    // Simulação de teste de rede
    await new Promise(resolve => setTimeout(resolve, 2500));

    // Sucesso aleatório para demonstração ou baseado em preenchimento
    if (emailConfig.useSmtp && emailConfig.smtpHost.includes('exemplo')) {
      setTestStatus('error');
    } else {
      setTestStatus('success');
    }

    // Voltar ao estado idle após 4 segundos de feedback
    setTimeout(() => setTestStatus('idle'), 4000);
  };

  const addNotice = () => {
    const newNotice: Notice = { id: Date.now().toString(), text: "Novo aviso...", active: true };
    setNotices([...notices, newNotice]);
  };
  const removeNotice = (id: string) => setNotices(notices.filter(n => n.id !== id));
  const updateNotice = (id: string, text: string) => setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  const toggleNotice = (id: string) => setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));

  const addReview = () => {
    const newReview: Review = { id: Date.now().toString(), author: "Novo Autor", text: "Conteúdo...", time: "Agora mesmo", initials: "NA", color: "#f8c8c4" };
    setReviews([...reviews, newReview]);
  };
  const removeReview = (id: string) => setReviews(reviews.filter(r => r.id !== id));
  const updateReview = (id: string, field: keyof Review, value: string) => setReviews(reviews.map(r => r.id === id ? { ...r, [field]: value } : r));

  const addPartner = () => {
    const newPartner: Partner = { id: Date.now().toString(), name: "Novo Parceiro", logo: "", url: "https://" };
    setPartners([...partners, newPartner]);
  };
  const removePartner = (id: string) => setPartners(partners.filter(p => p.id !== id));
  const updatePartner = (id: string, field: keyof Partner, value: string) => setPartners(partners.map(p => p.id === id ? { ...p, [field]: value } : p));

  const handleFinalize = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      onClose();
    }, 1200);
  };

  return (
    <motion.div 
      initial={{ opacity: 0, x: '100%' }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: '100%' }}
      className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto"
    >
      <div className="container mx-auto px-8 md:px-32 py-24 pb-32">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-16 gap-8">
          <div className="flex items-center gap-8">
            <h2 className="heading-serif text-4xl md:text-7xl">{t.adminTitle}</h2>
            <div className="flex flex-col">
              <div className={`flex items-center gap-3 transition-all duration-500 ${isSyncing ? 'text-[#f8c8c4]' : 'text-white/10'}`}>
                <Cloud size={16} className={isSyncing ? "animate-pulse" : ""} />
                <span className="text-[8px] font-black tracking-[0.3em] uppercase">{isSyncing ? "Sincronizando..." : "Persistido"}</span>
              </div>
            </div>
          </div>
          <div className="flex gap-6 items-center">
            <button onClick={onResetDefaults} className="flex items-center gap-3 text-[9px] font-bold tracking-widest uppercase text-white/20 hover:text-red-400 transition-colors border border-white/5 px-4 py-2 hover:border-red-400/30">
              <RotateCcw size={12}/> Resetar Padrões
            </button>
            <div className="h-8 w-[1px] bg-white/5 mx-2" />
            <button onClick={onLogout} className="text-[10px] font-bold tracking-widest uppercase text-white/40 hover:text-white transition-colors">Sair</button>
            <button onClick={onClose} className="text-white/20 hover:text-white transition-colors ml-4"><X size={32}/></button>
          </div>
        </div>

        {/* Tabs */}
        <div className="flex gap-16 border-b border-white/5 mb-16 overflow-x-auto whitespace-nowrap scrollbar-hide">
          {['slides', 'images', 'email', 'notices', 'reviews', 'partners'].map((tab) => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`pb-4 text-[11px] font-bold tracking-[0.5em] uppercase transition-all ${activeTab === tab ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20'}`}>
              {t[`admin${tab.charAt(0).toUpperCase() + tab.slice(1)}` as keyof typeof t] || tab}
            </button>
          ))}
        </div>

        {/* Forms Content */}
        <div className="min-h-[50vh]">
          {activeTab === 'slides' && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {slides.map(s => (
                  <div key={s.id} className="crystal-card p-10 relative space-y-6">
                    <button onClick={() => removeSlide(s.id)} className="absolute top-6 right-6 text-red-500/30 hover:text-red-500"><Trash2 size={16}/></button>
                    <input value={s.image} onChange={e => updateSlide(s.id, 'image', e.target.value)} placeholder="URL da Imagem" className="admin-input" />
                    <input value={s.title} onChange={e => updateSlide(s.id, 'title', e.target.value)} placeholder="Título" className="admin-input font-bold" />
                    <textarea value={s.description} onChange={e => updateSlide(s.id, 'description', e.target.value)} placeholder="Descrição" className="admin-input text-xs" rows={2} />
                  </div>
                ))}
              </div>
              <button onClick={addSlide} className="admin-btn-add"><Plus size={16}/> {t.adminSlides}</button>
            </div>
          )}

          {activeTab === 'images' && (
            <div className="space-y-12 max-w-4xl mx-auto">
              <div className="crystal-card p-12 space-y-10 border-[#f8c8c4]/10">
                <div className="flex items-center gap-6 text-[#f8c8c4]/60 mb-4">
                  <ImageIcon size={24}/>
                  <h3 className="text-xl font-bold tracking-widest uppercase">Imagens das Sessões</h3>
                </div>

                <div className="space-y-8">
                  <div className="space-y-2 group">
                    <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase group-focus-within:text-[#f8c8c4] transition-colors italic">Imagem Sessão "SOBRE"</label>
                    <input 
                      value={sectionImages.about} 
                      onChange={e => updateSectionImage('about', e.target.value)} 
                      placeholder="URL da foto na página Sobre" 
