                    <button 
                      onClick={() => updateEmailConfig('useSmtp', !emailConfig.useSmtp)}
                      className={`w-10 h-5 rounded-full relative transition-colors ${emailConfig.useSmtp ? 'bg-[#f8c8c4]' : 'bg-white/10'}`}
                    >
                      <motion.div 
                        animate={{ x: emailConfig.useSmtp ? 20 : 0 }}
                        className="w-4 h-4 bg-white rounded-full absolute top-0.5 left-0.5"
