                    </button>
                  </div>
                </div>

                <div className="space-y-8">
                  <div className="space-y-2 group">
                    <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase group-focus-within:text-[#f8c8c4] transition-colors">E-mail de Recebimento</label>
                    <input 
