            <button className={`lg:hidden relative z-[1100] transition-colors duration-300 ${isMenuOpen ? 'text-[#f8c8c4]' : 'text-white/60'}`} onClick={() => setIsMenuOpen(!isMenuOpen)}>
              {isMenuOpen ? <X size={28} /> : <Menu size={28} />}
