  Info, Lightbulb, Check, Database, Download, Upload, FileJson, ExternalLink
} from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface SectionImages {
  about: string;
  careers: string;
}

interface EmailConfig {
  recipientEmail: string;
  serviceId: string;
  templateId: string;
  publicKey: string;
  smtpHost: string;
  smtpPort: string;
  smtpUser: string;
  smtpPass: string;
  smtpSecure: boolean;
  useSmtp: boolean;
}

