const App = () => {
  const [lang, setLang] = useState<Language>('PT');
  const [view, setView] = useState<View>('home');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isLoginOpen, setIsLoginOpen] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeAdminTab, setActiveAdminTab] = useState<'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email' | 'database'>('slides');
  const [isSyncing, setIsSyncing] = useState(false);
  const [cloudStatus, setCloudStatus] = useState<'idle' | 'loading' | 'connected' | 'error'>('idle');

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);

  const STORAGE_KEY_PREFIX = 'rosimeire_config_v12';

  // --- Base State Initialization ---
  const [slides, setSlides] = useState<Slide[]>(DEFAULT_SLIDES);
  const [sectionImages, setSectionImages] = useState<SectionImages>(DEFAULT_SECTION_IMAGES);
  const [emailConfig, setEmailConfig] = useState<EmailConfig>(DEFAULT_EMAIL_CONFIG);
  const [notices, setNotices] = useState<Notice[]>(DEFAULT_NOTICES);
  const [reviews, setReviews] = useState<Review[]>(DEFAULT_REVIEWS);
  const [partners, setPartners] = useState<Partner[]>(DEFAULT_PARTNERS);
  const [googleMapsLink, setGoogleMapsLink] = useState<string>(INITIAL_GOOGLE_MAPS_LINK);
  const [gasUrl, setGasUrl] = useState<string>(() => localStorage.getItem(`${STORAGE_KEY_PREFIX}_gas_url`) || FIXED_GAS_URL);

  // --- Cloud Sync Implementation ---
  const fetchFromCloud = async (url: string) => {
    if (!url) return;
    setCloudStatus('loading');
    try {
      // Usamos cache: 'no-store' para garantir que pegamos os dados mais recentes da planilha
      const response = await fetch(url, { cache: 'no-store' });
      const data = await response.json();

      if (data && data.slides) {
        setSlides(data.slides);
        setSectionImages(data.sectionImages || DEFAULT_SECTION_IMAGES);
        setEmailConfig(data.emailConfig || DEFAULT_EMAIL_CONFIG);
        setNotices(data.notices || DEFAULT_NOTICES);
        setReviews(data.reviews || DEFAULT_REVIEWS);
        setPartners(data.partners || DEFAULT_PARTNERS);
        setGoogleMapsLink(data.googleMapsLink || INITIAL_GOOGLE_MAPS_LINK);
        setCloudStatus('connected');
      }
    } catch (err) {
      console.error("Erro ao sincronizar com nuvem:", err);
      setCloudStatus('error');
    }
  };

  const publishToCloud = async (url: string) => {
    if (!url) return;
    setIsSyncing(true);
    setCloudStatus('loading');
    try {
      const payload = {
        slides, sectionImages, emailConfig, notices, reviews, partners, googleMapsLink,
        version: "1.2",
        lastSync: new Date().toISOString()
      };

      // CRITICAL: Google Apps Script redireciona e não suporta preflight OPTIONS nativo para JSON.
      // Usamos 'no-cors' e enviamos como texto para garantir que os dados cheguem.
      await fetch(url, {
        method: 'POST',
        mode: 'no-cors',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify(payload)
      });

      // Como 'no-cors' não permite ler a resposta, assumimos sucesso se a requisição não disparar erro
      setCloudStatus('connected');
      setTimeout(() => setIsSyncing(false), 2000);
    } catch (err) {
      console.error("Erro ao publicar:", err);
      setCloudStatus('error');
      setIsSyncing(false);
    }
  };

  // --- Initial Load & Persistence ---
  useEffect(() => {
    const localSlides = localStorage.getItem(`${STORAGE_KEY_PREFIX}_slides`);
    if (localSlides) {
      setSlides(JSON.parse(localSlides));
      setSectionImages(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_section_images`) || "{}"));
      setEmailConfig(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_email_config`) || "{}"));
      setNotices(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_notices`) || "[]"));
      setReviews(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_reviews`) || "[]"));
      setPartners(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_partners`) || "[]"));
      setGoogleMapsLink(localStorage.getItem(`${STORAGE_KEY_PREFIX}_maps`) || INITIAL_GOOGLE_MAPS_LINK);
    }

    if (gasUrl) {
      fetchFromCloud(gasUrl);
    }
  }, []);

  useEffect(() => {
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_slides`, JSON.stringify(slides));
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_section_images`, JSON.stringify(sectionImages));
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_email_config`, JSON.stringify(emailConfig));
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_notices`, JSON.stringify(notices));
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_reviews`, JSON.stringify(reviews));
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_partners`, JSON.stringify(partners));
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_maps`, googleMapsLink);
    localStorage.setItem(`${STORAGE_KEY_PREFIX}_gas_url`, gasUrl);
  }, [slides, sectionImages, emailConfig, notices, reviews, partners, googleMapsLink, gasUrl]);

  const [currentSlide, setCurrentSlide] = useState(0);
  const [currentReviewIndex, setCurrentReviewIndex] = useState(0);
  const [formStatus, setFormStatus] = useState<'idle' | 'sending' | 'success'>('idle');
  const t = translations[lang];

  useEffect(() => {
    const interval = setInterval(() => setCurrentSlide(p => (p + 1) % (slides.length || 1)), 9000);
    return () => clearInterval(interval);
  }, [slides]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (reviews.length > 0) {
        setCurrentReviewIndex(prev => (prev + 1) % reviews.length);
      }
    }, 8000);
    return () => clearInterval(interval);
  }, [reviews]);

  const handleResetDefaults = () => {
    if (confirm("Tem certeza que deseja apagar todas as personalizações e voltar aos padrões de fábrica?")) {
      localStorage.clear();
      window.location.reload();
    }
  };

  useEffect(() => { window.scrollTo(0, 0); }, [view]);

  const handleAdminAccess = () => {
    if (isAuthenticated) setIsAdminOpen(true);
    else setIsLoginOpen(true);
    setIsMenuOpen(false);
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'admin' && password === 'rosimeire2025') {
      setIsAuthenticated(true);
      setIsLoginOpen(false);
      setIsAdminOpen(true);
    } else setLoginError(true);
  };

  const handleNavClick = (sectionId: string) => {
    setView('home');
    setIsMenuOpen(false);
