              </div>
            </div>
            <div className="grid grid-cols-2 gap-12">
              <div className="flex flex-col gap-4">
                <button onClick={() => setView('about')} className="text-[11px] font-bold uppercase tracking-[0.4em] text-white/30 hover:text-[#f8c8c4]">{t.footerSobre}</button>
                <button onClick={() => setView('careers')} className="text-[11px] font-bold uppercase tracking-[0.4em] text-white/30 hover:text-[#f8c8c4]">{t.footerCarreira}</button>
              </div>
            </div>
          </div>
          <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">© 2025. Rosimeire Serviços - Algarve.</p>
        </div>
