    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon, 
  Briefcase, CheckCircle, Image as ImageIcon, RotateCcw, Cloud, Mail, 
  Key, Server, Eye, EyeOff, ShieldCheck, Zap, AlertCircle, Loader2, 
  Info, Lightbulb, Check, Database, Download, Upload, FileJson, ExternalLink, Link, RefreshCw, CloudOff,
  Instagram, Linkedin
} from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface SectionImages {
  about: string;
  careers: string;
}

interface SocialLinks {
  instagram: string;
  linkedin: string;
}

interface EmailConfig {
  recipientEmail: string;
  serviceId: string;
  templateId: string;
  publicKey: string;
  smtpHost: string;
  smtpPort: string;
  smtpUser: string;
  smtpPass: string;
  smtpSecure: boolean;
  useSmtp: boolean;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface Review {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar?: string;
  initials: string;
  color: string;
}

interface Partner {
  id: string;
  name: string;
  logo: string;
  url: string;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  sectionImages: SectionImages;
  setSectionImages: (imgs: SectionImages) => void;
  socialLinks: SocialLinks;
  setSocialLinks: (links: SocialLinks) => void;
  emailConfig: EmailConfig;
  setEmailConfig: (config: EmailConfig) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  reviews: Review[];
  setReviews: (reviews: Review[]) => void;
  partners: Partner[];
  setPartners: (partners: Partner[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: 'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email' | 'database';
  setActiveTab: (tab: any) => void;
  t: any;
  isSyncing: boolean;
  onResetDefaults: () => void;
  gasUrl: string;
  setGasUrl: (url: string) => void;
  onPublishToCloud: () => void;
  cloudStatus: 'idle' | 'loading' | 'connected' | 'error';
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, sectionImages, setSectionImages, socialLinks, setSocialLinks, emailConfig, setEmailConfig, notices, setNotices, reviews, setReviews, 
  partners, setPartners, googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t, isSyncing, onResetDefaults, gasUrl, setGasUrl, onPublishToCloud, cloudStatus
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  // Handlers
  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0]?.image || "", tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };
  const removeSlide = (id: string) => slides.length > 1 && setSlides(slides.filter(s => s.id !== id));
  const updateSlide = (id: string, field: keyof Slide, value: string) => setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));

  const updateSectionImage = (key: keyof SectionImages, value: string) => setSectionImages({ ...sectionImages, [key]: value });

  const updateSocialLink = (key: keyof SocialLinks, value: string) => setSocialLinks({ ...socialLinks, [key]: value });

  const updateEmailConfig = (key: keyof EmailConfig, value: any) => {
    setEmailConfig({ ...emailConfig, [key]: value });
  };

  const addNotice = () => setNotices([...notices, { id: Date.now().toString(), text: "Novo aviso...", active: true }]);
  const removeNotice = (id: string) => setNotices(notices.filter(n => n.id !== id));
  const updateNotice = (id: string, text: string) => setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  const toggleNotice = (id: string) => setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));

  const addReview = () => setReviews([...reviews, { id: Date.now().toString(), author: "Novo Autor", text: "Conteúdo...", time: "Agora mesmo", initials: "NA", color: "#f8c8c4" }]);
  const removeReview = (id: string) => setReviews(reviews.filter(r => r.id !== id));
  const updateReview = (id: string, field: keyof Review, value: string) => setReviews(reviews.map(r => r.id === id ? { ...r, [field]: value } : r));

  const addPartner = () => setPartners([...partners, { id: Date.now().toString(), name: "Novo Parceiro", logo: "", url: "https://" }]);
  const removePartner = (id: string) => setPartners(partners.filter(p => p.id !== id));
  const updatePartner = (id: string, field: keyof Partner, value: string) => setPartners(partners.map(p => p.id === id ? { ...p, [field]: value } : p));

  // --- Database Management ---
  const exportDatabase = () => {
    const data = { slides, sectionImages, socialLinks, emailConfig, notices, reviews, partners, googleMapsLink, version: "1.1", exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `rosimeire_servicos_db_${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importDatabase = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (confirm("Isto irá substituir todos os dados atuais. Continuar?")) {
          if (data.slides) setSlides(data.slides);
          if (data.sectionImages) setSectionImages(data.sectionImages);
          if (data.socialLinks) setSocialLinks(data.socialLinks);
          if (data.emailConfig) setEmailConfig(data.emailConfig);
          if (data.notices) setNotices(data.notices);
          if (data.reviews) setReviews(data.reviews);
          if (data.partners) setPartners(data.partners);
          if (data.googleMapsLink) setGoogleMapsLink(data.googleMapsLink);
        }
      } catch (err) { alert("Erro ao importar JSON."); }
    };
    reader.readAsText(file);
  };

  const handleFinalize = () => {
    setIsSaving(true);
    setTimeout(() => { setIsSaving(false); onClose(); }, 1200);
  };

  return (
    <motion.div 
      initial={{ opacity: 0, x: '100%' }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: '100%' }}
      className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto"
    >
      <div className="container mx-auto px-8 md:px-32 py-24 pb-32">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-8">
          <div className="flex items-center gap-8">
            <h2 className="heading-serif text-4xl md:text-7xl">Painel de Controlo</h2>
            <div className={`flex items-center gap-3 px-4 py-2 rounded-full bg-white/5 border border-white/5 transition-all duration-500`}>
              {cloudStatus === 'loading' ? <RefreshCw size={14} className="text-blue-400 animate-spin" /> : 
               cloudStatus === 'connected' ? <Cloud size={14} className="text-green-400" /> : 
               cloudStatus === 'error' ? <CloudOff size={14} className="text-red-400" /> : 
               <CloudOff size={14} className="text-white/20" />}
              <span className="text-[10px] font-black tracking-[0.3em] uppercase">
                {cloudStatus === 'connected' ? 'Cloud OK' : cloudStatus === 'loading' ? 'Sync...' : 'Offline'}
              </span>
            </div>
          </div>
          <div className="flex gap-6 items-center">
            <button onClick={onLogout} className="text-[10px] font-bold tracking-widest uppercase text-white/40 hover:text-white transition-colors">Sair</button>
            <button onClick={onClose} className="text-white/20 hover:text-white transition-colors ml-4"><X size={32}/></button>
          </div>
        </div>

        {/* --- INFORMATIVO DA BASE DE DADOS (ACIMA DOS SEPARADORES) --- */}
        <motion.div 
          initial={{ opacity: 0, y: -10 }} 
          animate={{ opacity: 1, y: 0 }}
          className="mb-8 p-6 bg-[#f8c8c4]/5 border border-[#f8c8c4]/20 rounded-sm flex flex-col md:flex-row items-center justify-between gap-6"
        >
          <div className="flex items-center gap-6 w-full overflow-hidden">
            <div className="p-4 bg-[#f8c8c4]/10 rounded-full flex-shrink-0">
              <Database size={20} className="text-[#f8c8c4]" />
            </div>
            <div className="overflow-hidden">
              <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#f8c8c4] mb-1">Link Base de Dados Ativa</p>
              <p className="text-[11px] font-mono text-white/40 truncate select-all">{gasUrl}</p>
            </div>
          </div>
          <div className="flex gap-4 w-full md:w-auto">
            <a 
              href={gasUrl} 
              target="_blank" 
              rel="noopener noreferrer" 
              className="flex-1 md:flex-none flex items-center justify-center gap-3 px-6 py-3 bg-[#f8c8c4]/10 border border-[#f8c8c4]/20 text-[9px] font-black uppercase tracking-widest text-[#f8c8c4] hover:bg-[#f8c8c4]/20 transition-all"
            >
              Testar API <ExternalLink size={12}/>
            </a>
          </div>
        </motion.div>

        {/* Tabs / Separadores */}
        <div className="flex gap-12 border-b border-white/5 mb-16 overflow-x-auto whitespace-nowrap scrollbar-hide">
          {[
            { id: 'slides', icon: <ImageIcon size={14}/>, label: 'Slides' },
            { id: 'images', icon: <ImageIcon size={14}/>, label: 'Visual' },
            { id: 'email', icon: <Mail size={14}/>, label: 'Contacto & Social' },
            { id: 'notices', icon: <Bell size={14}/>, label: 'Avisos' },
            { id: 'reviews', icon: <Star size={14}/>, label: 'Depoimentos' },
            { id: 'partners', icon: <Briefcase size={14}/>, label: 'Parceiros' },
            { id: 'database', icon: <Database size={14}/>, label: 'Dados & Nuvem' }
          ].map((tab) => (
            <button 
              key={tab.id} onClick={() => setActiveTab(tab.id as any)} 
              className={`pb-4 text-[10px] font-bold tracking-[0.3em] uppercase transition-all flex items-center gap-3 ${activeTab === tab.id ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20 hover:text-white/40'}`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="min-h-[50vh]">
          {activeTab === 'slides' && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {slides.map(s => (
                  <div key={s.id} className="crystal-card p-10 relative space-y-6">
                    <button onClick={() => removeSlide(s.id)} className="absolute top-6 right-6 text-red-500/30 hover:text-red-500"><Trash2 size={16}/></button>
                    <input value={s.image} onChange={e => updateSlide(s.id, 'image', e.target.value)} placeholder="URL da Imagem" className="admin-input" />
                    <input value={s.title} onChange={e => updateSlide(s.id, 'title', e.target.value)} placeholder="Título" className="admin-input font-bold" />
                    <textarea value={s.description} onChange={e => updateSlide(s.id, 'description', e.target.value)} placeholder="Descrição" className="admin-input text-xs" rows={2} />
                  </div>
                ))}
              </div>
              <button onClick={addSlide} className="admin-btn-add"><Plus size={16}/> Adicionar Novo Slide</button>
            </div>
          )}

          {activeTab === 'database' && (
            <div className="max-w-4xl mx-auto space-y-12">
              {/* Cloud Integration Panel */}
              <div className="crystal-card p-12 border-[#f8c8c4]/20 space-y-10 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><Cloud size={180} /></div>
                <div className="flex items-center gap-6 text-[#f8c8c4]">
                  <Cloud size={28} />
                  <div>
                    <h3 className="text-xl font-bold tracking-widest uppercase text-white">Base de Dados Global (GAS)</h3>
                    <p className="text-[10px] font-bold tracking-[0.3em] text-[#f8c8c4]/60 uppercase">Conexão Estabelecida</p>
                  </div>
                </div>

                {/* Fixed Link Notice in Database Tab */}
                <div className="bg-[#f8c8c4]/10 border border-[#f8c8c4]/20 p-6 rounded-sm flex items-start gap-4">
                  <LinkIcon size={16} className="text-[#f8c8c4] flex-shrink-0 mt-1" />
                  <div className="space-y-1">
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-[#f8c8c4]">Endpoint Principal Ativo:</p>
                    <p className="text-[9px] font-mono text-white/60 break-all">{gasUrl}</p>
                  </div>
                </div>

                <div className="space-y-8 relative z-10">
                   <div className="space-y-2 group">
                      <div className="flex justify-between items-center">
                        <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase italic">Google Apps Script URL</label>
                        <a href="#" className="text-[9px] text-[#f8c8c4]/40 hover:text-[#f8c8c4] flex items-center gap-2 tracking-widest uppercase">Ver Tutorial <ExternalLink size={10}/></a>
                      </div>
                      <input 
                        value={gasUrl} 
                        onChange={e => setGasUrl(e.target.value)} 
                        placeholder="https://script.google.com/macros/s/.../exec" 
                        className="admin-input font-mono text-[10px]" 
                      />
                   </div>

                   <div className="flex flex-col md:flex-row gap-6">
                      <button 
                        onClick={onPublishToCloud}
                        disabled={!gasUrl || isSyncing}
                        className={`flex-1 flex items-center justify-center gap-4 py-6 border border-[#f8c8c4] text-[#f8c8c4] hover:bg-[#f8c8c4] hover:text-[#081221] transition-all rounded-sm uppercase text-[11px] font-black tracking-widest ${(!gasUrl || isSyncing) ? 'opacity-30 cursor-not-allowed grayscale' : ''}`}
                      >
                        {isSyncing ? <Loader2 size={16} className="animate-spin" /> : <Cloud size={16} />}
                        Publicar na Nuvem (Live)
                      </button>
                      <button 
                        onClick={() => window.location.reload()}
                        className="px-10 py-6 border border-white/5 text-white/30 hover:text-white transition-all uppercase text-[11px] font-black tracking-widest"
                      >
                        Forçar Refresh
                      </button>
                   </div>

                   <div className="p-6 bg-[#f8c8c4]/5 rounded-sm border border-[#f8c8c4]/10">
                      <div className="flex gap-4 text-[#f8c8c4]/60"><Info size={16} className="flex-shrink-0" /><p className="text-[10px] font-medium leading-relaxed uppercase tracking-wider">A URL acima é a sua base de dados principal. Todos os dados editados no painel só serão visíveis para o público após clicar em **Publicar na Nuvem**.</p></div>
                   </div>
                </div>
              </div>

              {/* Local Backup Panel */}
