              <h3 className="heading-serif text-2xl text-center mb-8">Acesso Restrito</h3>
              <form onSubmit={handleLogin} className="space-y-6">
                <input placeholder="Utilizador" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none" />
                <input placeholder="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none" />
                <button type="submit" className="w-full btn-serenity">Entrar</button>
              </form>
              {loginError && <p className="text-red-400 text-[10px] text-center mt-4">Credenciais incorretas.</p>}
              <button onClick={() => setIsLoginOpen(false)} className="w-full text-[10px] text-white/20 uppercase mt-4">Cancelar</button>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* --- FOOTER --- */}
      <footer className="py-24 bg-[#040911] border-t border-white/5">
        <div className="container mx-auto px-8 md:px-16">
          <div className="flex flex-col md:flex-row justify-between items-start gap-16 mb-24">
            <div className="text-left">
              <h5 className="text-white font-light tracking-[0.4em] text-lg mb-8 uppercase">ROSIMEIRE SERVIÇOS</h5>
              <p className="text-[10px] font-bold tracking-[0.5em] text-white/20 uppercase max-w-xs">{t.footerNote}</p>
            </div>

            <div className="grid grid-cols-2 gap-24">
              <div className="flex flex-col gap-6">
                <div className="flex gap-6">
                  <a href={socialLinks.instagram} target="_blank" rel="noopener noreferrer" className="text-white/20 hover:text-[#f8c8c4] transition-all transform hover:scale-110 active:scale-95">
                    <Instagram size={20} />
                  </a>
                  <a href={socialLinks.linkedin} target="_blank" rel="noopener noreferrer" className="text-white/20 hover:text-[#f8c8c4] transition-all transform hover:scale-110 active:scale-95">
                    <Linkedin size={20} />
                  </a>
                </div>
              </div>

              <div className="flex flex-col gap-6">
                <button onClick={() => setView('about')} className="text-[11px] font-bold uppercase tracking-[0.4em] text-white/30 hover:text-[#f8c8c4] transition-colors text-left">{t.footerSobre}</button>
                <button onClick={() => setView('careers')} className="text-[11px] font-bold uppercase tracking-[0.4em] text-white/30 hover:text-[#f8c8c4] transition-colors text-left">{t.footerCarreira}</button>
              </div>
            </div>
          </div>
          <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">© 2025. Rosimeire Serviços - Algarve.</p>
        </div>
      </footer>
    </div>
  );
};

