                </div>
                <div className="crystal-card p-12 rounded-sm">
                  <form onSubmit={handleContactSubmit} className="space-y-12">
                    <div className="space-y-2"><label className="tagline block">{t.name}</label><input required className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" /></div>
                    <div className="space-y-2"><label className="tagline block">{t.message}</label><textarea required rows={4} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" /></div>
                    <button className="w-full btn-serenity py-8">{formStatus === 'idle' ? t.send : '...'}</button>
                  </form>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AdminPanel 
        isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
        slides={slides} setSlides={setSlides}
        sectionImages={sectionImages} setSectionImages={setSectionImages}
        socialLinks={socialLinks} setSocialLinks={setSocialLinks}
        emailConfig={emailConfig} setEmailConfig={setEmailConfig}
        notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews}
        partners={partners} setPartners={setPartners}
        googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink}
        activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={t}
        isSyncing={isSyncing} onResetDefaults={handleResetDefaults}
        gasUrl={gasUrl} setGasUrl={setGasUrl} onPublishToCloud={() => publishToCloud(gasUrl)}
        cloudStatus={cloudStatus}
      />

      <AnimatePresence>
        {isLoginOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1200] flex items-center justify-center bg-[#081221]/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="crystal-card p-12 max-w-sm w-full">
              <h3 className="heading-serif text-2xl text-center mb-8 uppercase tracking-widest">Acesso Restrito</h3>
              <form onSubmit={handleLogin} className="space-y-6">
                <input placeholder="Utilizador" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none text-sm placeholder:text-white/20" />
                <input placeholder="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none text-sm placeholder:text-white/20" />
                <button type="submit" className="w-full btn-serenity flex items-center justify-center gap-3"><Lock size={12}/> Entrar</button>
              </form>

              <div className="mt-8 pt-8 border-t border-white/5 flex flex-col gap-4">
                <button 
                  onClick={handleDemoAccess} 
                  className="w-full py-3 border border-dashed border-[#f8c8c4]/30 text-[9px] font-black tracking-[0.4em] uppercase text-[#f8c8c4] hover:bg-[#f8c8c4]/5 transition-all flex items-center justify-center gap-3"
                >
                  <Zap size={10}/> Acesso DEMO
                </button>
                <button onClick={() => setIsLoginOpen(false)} className="w-full text-[9px] font-bold tracking-[0.3em] text-white/20 uppercase hover:text-white/40 transition-colors">Cancelar</button>
              </div>

              {loginError && <p className="text-red-400 text-[10px] font-bold text-center mt-6 uppercase tracking-widest">Credenciais incorretas.</p>}
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-24 bg-[#040911] border-t border-white/5">
        <div className="container mx-auto px-8 md:px-16">
          <div className="flex flex-col md:flex-row justify-between items-start gap-16 mb-24">
            <div className="text-left">
              <h5 className="text-white font-light tracking-[0.4em] text-lg mb-8 uppercase">ROSIMEIRE SERVIÇOS</h5>
              <p className="text-[10px] font-bold tracking-[0.5em] text-white/20 uppercase max-w-xs">{t.footerNote}</p>
            </div>

            <div className="grid grid-cols-2 gap-24">
              <div className="flex flex-col gap-6">
                <div className="flex gap-6">
                  <a href={socialLinks.instagram} target="_blank" rel="noopener noreferrer" className="text-white/20 hover:text-[#f8c8c4] transition-all transform hover:scale-110 active:scale-95"><Instagram size={20} /></a>
                  <a href={socialLinks.linkedin} target="_blank" rel="noopener noreferrer" className="text-white/20 hover:text-[#f8c8c4] transition-all transform hover:scale-110 active:scale-95"><Linkedin size={20} /></a>
                </div>
              </div>

              <div className="flex flex-col gap-6">
                <button onClick={() => setView('about')} className="text-[11px] font-bold uppercase tracking-[0.4em] text-white/30 hover:text-[#f8c8c4] transition-colors text-left">{t.footerSobre}</button>
                <button onClick={() => setView('careers')} className="text-[11px] font-bold uppercase tracking-[0.4em] text-white/30 hover:text-[#f8c8c4] transition-colors text-left">{t.footerCarreira}</button>
              </div>
            </div>
          </div>

          <div className="pt-16 border-t border-white/5 flex flex-col md:flex-row justify-between items-center gap-8">
            <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">© 2025. Rosimeire Serviços - Algarve.</p>

            {/* Assinatura do Desenvolvedor */}
            <div className="flex items-center gap-5 text-white/10 group cursor-default">
              <div className="flex flex-col text-right">
                <span className="text-[7px] font-black tracking-[0.3em] uppercase text-white/20 mb-1">{t.developedBy}</span>
                <span className="text-[9px] font-bold tracking-[0.1em] text-white/40 uppercase group-hover:text-[#f8c8c4] transition-colors">Bob Harrisson Gracindo Madeiro</span>
                <span className="text-[7px] font-medium tracking-[0.4em] text-[#f8c8c4]/30 uppercase italic">IT Depart.</span>
              </div>
              <div className="w-[1px] h-8 bg-white/5 group-hover:bg-[#f8c8c4]/20 transition-colors"></div>
              <div className="p-2.5 border border-white/5 rounded-sm group-hover:border-[#f8c8c4]/30 transition-all duration-500">
                <Code size={14} className="group-hover:text-[#f8c8c4] transition-colors opacity-30 group-hover:opacity-100" />
              </div>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon, 
  Briefcase, CheckCircle, Image as ImageIcon, RotateCcw, Cloud, Mail, 
  Key, Server, Eye, EyeOff, ShieldCheck, Zap, AlertCircle, Loader2, 
  Info, Lightbulb, Check, Database, Download, Upload, FileJson, ExternalLink, Link, RefreshCw, CloudOff,
  Instagram, Linkedin
} from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
}

interface SectionImages {
  about: string;
  careers: string;
}

interface SocialLinks {
  instagram: string;
  linkedin: string;
}

interface EmailConfig {
  recipientEmail: string;
  serviceId: string;
  templateId: string;
  publicKey: string;
  smtpHost: string;
  smtpPort: string;
  smtpUser: string;
  smtpPass: string;
  smtpSecure: boolean;
  useSmtp: boolean;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface Review {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar?: string;
  initials: string;
  color: string;
}

interface Partner {
  id: string;
  name: string;
  logo: string;
  url: string;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  sectionImages: SectionImages;
  setSectionImages: (imgs: SectionImages) => void;
  socialLinks: SocialLinks;
  setSocialLinks: (links: SocialLinks) => void;
  emailConfig: EmailConfig;
  setEmailConfig: (config: EmailConfig) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  reviews: Review[];
  setReviews: (reviews: Review[]) => void;
  partners: Partner[];
  setPartners: (partners: Partner[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: 'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email';
  setActiveTab: (tab: any) => void;
  t: any;
  isSyncing: boolean;
  onResetDefaults: () => void;
  gasUrl: string;
  setGasUrl: (url: string) => void;
  onPublishToCloud: () => Promise<boolean>;
  cloudStatus: 'idle' | 'loading' | 'connected' | 'error';
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, sectionImages, setSectionImages, socialLinks, setSocialLinks, emailConfig, setEmailConfig, notices, setNotices, reviews, setReviews, 
  partners, setPartners, googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t, isSyncing, onResetDefaults, gasUrl, setGasUrl, onPublishToCloud, cloudStatus
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  // Handlers
  const addSlide = () => {
    const newSlide: Slide = { id: Date.now().toString(), title: "Novo Slide", description: "Descrição...", image: slides[0]?.image || "", tag: "NOVO" };
    setSlides([...slides, newSlide]);
  };
  const removeSlide = (id: string) => slides.length > 1 && setSlides(slides.filter(s => s.id !== id));
  const updateSlide = (id: string, field: keyof Slide, value: string) => setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));

  const updateSectionImage = (key: keyof SectionImages, value: string) => setSectionImages({ ...sectionImages, [key]: value });

  const updateSocialLink = (key: keyof SocialLinks, value: string) => setSocialLinks({ ...socialLinks, [key]: value });

  const updateEmailConfig = (key: keyof EmailConfig, value: any) => {
    setEmailConfig({ ...emailConfig, [key]: value });
  };

  const addNotice = () => setNotices([...notices, { id: Date.now().toString(), text: "Novo aviso...", active: true }]);
  const removeNotice = (id: string) => setNotices(notices.filter(n => n.id !== id));
  const updateNotice = (id: string, text: string) => setNotices(notices.map(n => n.id === id ? { ...n, text } : n));
  const toggleNotice = (id: string) => setNotices(notices.map(n => n.id === id ? { ...n, active: !n.active } : n));

  const addReview = () => setReviews([...reviews, { id: Date.now().toString(), author: "Novo Autor", text: "Conteúdo...", time: "Agora mesmo", initials: "NA", color: "#f8c8c4" }]);
  const removeReview = (id: string) => setReviews(reviews.filter(r => r.id !== id));
  const updateReview = (id: string, field: keyof Review, value: string) => setReviews(reviews.map(r => r.id === id ? { ...r, [field]: value } : r));

  const addPartner = () => setPartners([...partners, { id: Date.now().toString(), name: "Novo Parceiro", logo: "", url: "https://" }]);
  const removePartner = (id: string) => setPartners(partners.filter(p => p.id !== id));
  const updatePartner = (id: string, field: keyof Partner, value: string) => setPartners(partners.map(p => p.id === id ? { ...p, [field]: value } : p));

  const handleFinalize = async () => {
    setIsSaving(true);
    // Sincronização automática antes de sair
    await onPublishToCloud();
    setTimeout(() => { setIsSaving(false); onClose(); }, 800);
  };

  return (
    <motion.div 
      initial={{ opacity: 0, x: '100%' }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: '100%' }}
      className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto"
    >
      <div className="container mx-auto px-8 md:px-32 py-24 pb-32">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 gap-8">
          <div className="flex items-center gap-8">
            <h2 className="heading-serif text-4xl md:text-7xl">Painel de Controlo</h2>
            <div className={`flex items-center gap-3 px-4 py-2 rounded-full bg-white/5 border border-white/5 transition-all duration-500`}>
              {cloudStatus === 'loading' ? <RefreshCw size={14} className="text-blue-400 animate-spin" /> : 
               cloudStatus === 'connected' ? <Cloud size={14} className="text-green-400" /> : 
               cloudStatus === 'error' ? <CloudOff size={14} className="text-red-400" /> : 
               <CloudOff size={14} className="text-white/20" />}
              <span className="text-[10px] font-black tracking-[0.3em] uppercase">
                {cloudStatus === 'connected' ? 'Sincronizado' : cloudStatus === 'loading' ? 'A Guardar...' : 'Offline'}
              </span>
            </div>
          </div>
          <div className="flex gap-6 items-center">
            <button onClick={onLogout} className="text-[10px] font-bold tracking-widest uppercase text-white/40 hover:text-white transition-colors">Sair</button>
            <button onClick={onClose} className="text-white/20 hover:text-white transition-colors ml-4"><X size={32}/></button>
          </div>
        </div>

        {/* Informação Técnica Flutuante sutil */}
        <div className="mb-12 flex items-center justify-between p-4 bg-white/[0.02] border border-white/5 rounded-sm">
           <div className="flex items-center gap-4">
             <Server size={14} className="text-[#f8c8c4]/40" />
             <span className="text-[9px] font-mono text-white/30 truncate max-w-xs">{gasUrl}</span>
           </div>
           <span className="text-[8px] font-black uppercase tracking-widest text-[#f8c8c4]/20">Sistema Integrado SIR</span>
        </div>

        {/* Tabs / Separadores */}
        <div className="flex gap-12 border-b border-white/5 mb-16 overflow-x-auto whitespace-nowrap scrollbar-hide">
          {[
            { id: 'slides', icon: <ImageIcon size={14}/>, label: 'Slides' },
            { id: 'images', icon: <ImageIcon size={14}/>, label: 'Visual' },
            { id: 'email', icon: <Mail size={14}/>, label: 'Contacto & Social' },
            { id: 'notices', icon: <Bell size={14}/>, label: 'Avisos' },
            { id: 'reviews', icon: <Star size={14}/>, label: 'Depoimentos' },
            { id: 'partners', icon: <Briefcase size={14}/>, label: 'Parceiros' }
          ].map((tab) => (
            <button 
              key={tab.id} onClick={() => setActiveTab(tab.id as any)} 
              className={`pb-4 text-[10px] font-bold tracking-[0.3em] uppercase transition-all flex items-center gap-3 ${activeTab === tab.id ? 'text-[#f8c8c4] border-b border-[#f8c8c4]' : 'text-white/20 hover:text-white/40'}`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>

        {/* Content */}
        <div className="min-h-[50vh]">
          {activeTab === 'slides' && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {slides.map(s => (
                  <div key={s.id} className="crystal-card p-10 relative space-y-6">
                    <button onClick={() => removeSlide(s.id)} className="absolute top-6 right-6 text-red-500/30 hover:text-red-500"><Trash2 size={16}/></button>
                    <input value={s.image} onChange={e => updateSlide(s.id, 'image', e.target.value)} placeholder="URL da Imagem" className="admin-input" />
                    <input value={s.title} onChange={e => updateSlide(s.id, 'title', e.target.value)} placeholder="Título" className="admin-input font-bold" />
                    <textarea value={s.description} onChange={e => updateSlide(s.id, 'description', e.target.value)} placeholder="Descrição" className="admin-input text-xs" rows={2} />
                  </div>
                ))}
              </div>
              <button onClick={addSlide} className="admin-btn-add"><Plus size={16}/> Adicionar Novo Slide</button>
            </div>
          )}

          {activeTab === 'images' && (
            <div className="space-y-12 max-w-4xl mx-auto">
              <div className="crystal-card p-12 space-y-10 border-[#f8c8c4]/10">
                <div className="flex items-center gap-6 text-[#f8c8c4]/60 mb-4">
                  <ImageIcon size={24}/>
                  <h3 className="text-xl font-bold tracking-widest uppercase text-white">Visual das Páginas</h3>
                </div>
                <div className="space-y-8">
                  <div className="space-y-2 group">
                    <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase italic">Foto da Página Sobre</label>
                    <input value={sectionImages.about} onChange={e => updateSectionImage('about', e.target.value)} placeholder="URL da foto" className="admin-input" />
                  </div>
                  <div className="space-y-2 group">
                    <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase italic">Foto da Página Carreiras</label>
                    <input value={sectionImages.careers} onChange={e => updateSectionImage('careers', e.target.value)} placeholder="URL da foto" className="admin-input" />
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'email' && (
            <div className="space-y-12 max-w-5xl mx-auto">
               <div className="crystal-card p-12 space-y-10 border-[#f8c8c4]/10">
                <div className="flex items-center gap-6 text-[#f8c8c4]/60"><Mail size={24}/><h3 className="text-xl font-bold tracking-widest uppercase text-white">Configurações de Contacto</h3></div>

                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold tracking-[0.4em] text-white/30 uppercase italic">E-mail de Recebimento</label>
                    <input type="email" value={emailConfig.recipientEmail} onChange={e => updateEmailConfig('recipientEmail', e.target.value)} className="admin-input" />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6 border-t border-white/5">
                    <div className="space-y-4">
                      <div className="flex items-center gap-3 text-[#f8c8c4]/60">
                        <Instagram size={14}/>
                        <label className="text-[10px] font-bold tracking-[0.4em] uppercase">Instagram URL</label>
                      </div>
                      <input value={socialLinks.instagram} onChange={e => updateSocialLink('instagram', e.target.value)} placeholder="https://instagram.com/..." className="admin-input" />
                    </div>
                    <div className="space-y-4">
                      <div className="flex items-center gap-3 text-[#f8c8c4]/60">
                        <Linkedin size={14}/>
                        <label className="text-[10px] font-bold tracking-[0.4em] uppercase">LinkedIn URL</label>
                      </div>
                      <input value={socialLinks.linkedin} onChange={e => updateSocialLink('linkedin', e.target.value)} placeholder="https://linkedin.com/in/..." className="admin-input" />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'notices' && (
            <div className="space-y-8 max-w-4xl mx-auto">
              {notices.map(n => (
                <div key={n.id} className="crystal-card p-8 flex items-center justify-between gap-8">
                  <input value={n.text} onChange={e => updateNotice(n.id, e.target.value)} className="admin-input flex-1" />
                  <div className="flex gap-4">
                    <button onClick={() => toggleNotice(n.id)} className={`p-4 border transition-all ${n.active ? 'border-[#f8c8c4] text-[#f8c8c4]' : 'border-white/5 text-white/10'}`}><Bell size={18}/></button>
                    <button onClick={() => removeNotice(n.id)} className="p-4 text-red-500/20 hover:text-red-500"><Trash2 size={18}/></button>
                  </div>
                </div>
              ))}
              <button onClick={addNotice} className="admin-btn-add"><Plus size={16}/> Novo Aviso</button>
            </div>
          )}

          {activeTab === 'reviews' && (
            <div className="space-y-12">
               <div className="crystal-card p-8 border-[#f8c8c4]/20 border-dashed">
                  <label className="text-[9px] font-bold tracking-[0.3em] text-[#f8c8c4]/60 uppercase mb-4 block">Link das Avaliações (Google Maps)</label>
                  <input value={googleMapsLink} onChange={e => setGoogleMapsLink(e.target.value)} className="admin-input" />
               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {reviews.map(r => (
                  <div key={r.id} className="crystal-card p-10 relative space-y-6">
                    <button onClick={() => removeReview(r.id)} className="absolute top-6 right-6 text-red-500/30 hover:text-red-500"><Trash2 size={16}/></button>
                    <div className="grid grid-cols-2 gap-4">
                      <input value={r.author} onChange={e => updateReview(r.id, 'author', e.target.value)} placeholder="Autor" className="admin-input font-bold" />
                      <input value={r.time} onChange={e => updateReview(r.id, 'time', e.target.value)} placeholder="Tempo" className="admin-input" />
                    </div>
                    <textarea value={r.text} onChange={e => updateReview(r.id, 'text', e.target.value)} className="admin-input" rows={3} />
                  </div>
                ))}
               </div>
               <button onClick={addReview} className="admin-btn-add"><Plus size={16}/> Adicionar Depoimento Manual</button>
            </div>
          )}

          {activeTab === 'partners' && (
            <div className="space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {partners.map(p => (
                  <div key={p.id} className="crystal-card p-10 relative space-y-6">
                    <button onClick={() => removePartner(p.id)} className="absolute top-6 right-6 text-red-500/30 hover:text-red-500"><Trash2 size={16}/></button>
                    <input value={p.name} onChange={e => updatePartner(p.id, 'name', e.target.value)} placeholder="Nome" className="admin-input font-bold" />
