      }
    }, 5000);
    return () => clearInterval(interval);
  }, [partners]);

  const handleNextSlide = () => setCurrentSlide(p => (p + 1) % (slides.length || 1));
  const handlePrevSlide = () => setCurrentSlide(p => (p - 1 + slides.length) % (slides.length || 1));

