interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: any[];
  setSlides: (slides: any[]) => void;
  sectionImages: any;
  setSectionImages: (imgs: any) => void;
  socialLinks: any;
  setSocialLinks: (links: any) => void;
  emailConfig: ContactConfig;
  setEmailConfig: (config: ContactConfig) => void;
  notices: any[];
  setNotices: (notices: any[]) => void;
  reviews: any[];
  setReviews: (reviews: any[]) => void;
  partners: any[];
  setPartners: (partners: any[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: string;
  setActiveTab: (tab: any) => void;
  t: any;
  isSyncing: boolean;
  onResetDefaults: () => void;
  gasUrl: string;
  setGasUrl: (url: string) => void;
  onPublishToCloud: () => Promise<boolean>;
  cloudStatus: string;
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, sectionImages, setSectionImages, socialLinks, setSocialLinks, emailConfig, setEmailConfig, notices, setNotices, reviews, setReviews, 
  partners, setPartners, googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t, isSyncing, onResetDefaults, gasUrl, setGasUrl, onPublishToCloud, cloudStatus
}) => {
  const [isSaving, setIsSaving] = useState(false);
  if (!isOpen) return null;

  const updateSlide = (id: string, field: string, value: string) => setSlides(slides.map(s => s.id === id ? { ...s, [field]: value } : s));
  const updateEmailConfig = (key: keyof ContactConfig, value: any) => setEmailConfig({ ...emailConfig, [key]: value });
  const updateSocialLink = (key: string, value: string) => setSocialLinks({ ...socialLinks, [key]: value });

  const handleFinalize = async () => {
    setIsSaving(true);
    await onPublishToCloud();
    setTimeout(() => { setIsSaving(false); onClose(); }, 800);
  };

  return (
    <motion.div initial={{ opacity: 0, x: '100%' }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: '100%' }} className="fixed inset-0 z-[1000] bg-[#081221] text-white overflow-y-auto">
      <div className="container mx-auto px-8 md:px-32 py-24">
        <div className="flex justify-between items-center mb-16">
          <h2 className="heading-serif text-5xl">Painel de Controlo</h2>
          <button onClick={onClose} className="text-white/20 hover:text-white"><X size={32}/></button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mb-16">
          {['slides', 'images', 'email', 'notices', 'reviews', 'partners'].map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`p-6 text-[10px] font-bold tracking-[0.3em] uppercase rounded-sm border ${activeTab === tab ? 'text-[#f8c8c4] border-[#f8c8c4] bg-[#f8c8c4]/5' : 'text-white/20 border-white/5'}`}>{tab}</button>
          ))}
        </div>

        <div className="min-h-[50vh]">
          {activeTab === 'email' && (
            <div className="space-y-12 max-w-4xl mx-auto">
               <div className="crystal-card p-12 space-y-12 border-[#f8c8c4]/10">
                <div className="flex items-center gap-6 text-[#f8c8c4]/60"><Mail size={24}/><h3 className="text-xl font-bold tracking-widest uppercase text-white">Dados de Contacto Público</h3></div>

                <div className="space-y-8">
                  <div className="space-y-2">
                    <label className="admin-label">E-mail de Recebimento / Exibição</label>
                    <input value={emailConfig.recipientEmail} onChange={e => updateEmailConfig('recipientEmail', e.target.value)} className="admin-input" />
                  </div>

                  <div className="space-y-2">
                    <label className="admin-label flex items-center gap-2">Telemóvel (Com DDI Ex: +351...) <Phone size={10}/></label>
                    <input value={emailConfig.phone} onChange={e => updateEmailConfig('phone', e.target.value)} className="admin-input" placeholder="+351 912 525 649" />
                  </div>

                  <div className="space-y-2">
                    <label className="admin-label flex items-center gap-2">Morada / Escritório <MapPin size={10}/></label>
                    <textarea value={emailConfig.address} onChange={e => updateEmailConfig('address', e.target.value)} className="admin-input" rows={2} />
                  </div>

                  <div className="grid grid-cols-2 gap-8 pt-8 border-t border-white/5">
                    <div className="space-y-2">
                      <label className="admin-label">Instagram URL</label>
                      <input value={socialLinks.instagram} onChange={e => updateSocialLink('instagram', e.target.value)} className="admin-input" />
                    </div>
                    <div className="space-y-2">
                      <label className="admin-label">LinkedIn URL</label>
                      <input value={socialLinks.linkedin} onChange={e => updateSocialLink('linkedin', e.target.value)} className="admin-input" />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'slides' && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {slides.map(s => (
                <div key={s.id} className="crystal-card p-10 space-y-6">
                  <div className="space-y-2"><label className="admin-label">Título</label><input value={s.title} onChange={e => updateSlide(s.id, 'title', e.target.value)} className="admin-input" /></div>
                  <div className="space-y-2"><label className="admin-label">Link (about, contact, careers)</label><input value={s.buttonLink} onChange={e => updateSlide(s.id, 'buttonLink', e.target.value)} className="admin-input" /></div>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="mt-24 pt-16 border-t border-white/5 flex flex-col items-center gap-8">
          <button onClick={handleFinalize} disabled={isSaving} className="btn-serenity px-32 py-8 flex items-center gap-6 min-w-[400px]">
            {isSaving ? <Loader2 className="animate-spin" /> : <><Check size={16} /> GUARDAR & FINALIZAR</>}
          </button>
        </div>
      </div>

      <style>{`
        .admin-label { display: block; font-size: 9px; font-weight: 700; letter-spacing: 0.3em; text-transform: uppercase; color: rgba(248, 200, 196, 0.4); margin-bottom: 0.5rem; }
        .admin-input { width: 100%; background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); padding: 1rem; color: white; font-size: 0.8rem; border-radius: 2px; outline: none; }
        .admin-input:focus { border-color: #f8c8c4; }
      `}</style>
    </motion.div>
  );
};

