  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [cloudStatus, setCloudStatus] = useState<'idle' | 'loading' | 'connected' | 'error'>('idle');

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);

  // Form State
  const [contactName, setContactName] = useState('');
  const [contactEmail, setContactEmail] = useState('');
  const [contactPhone, setContactPhone] = useState('');
  const [selectedCountry, setSelectedCountry] = useState(COUNTRY_CODES[0]);
  const [contactMessage, setContactMessage] = useState('');
  const [formStatus, setFormStatus] = useState<'idle' | 'sending' | 'success'>('idle');

  const STORAGE_KEY_PREFIX = 'rosimeire_config_v12';

  // --- Base State ---
  const [slides, setSlides] = useState<Slide[]>(DEFAULT_SLIDES);
  const [sectionImages, setSectionImages] = useState<SectionImages>(DEFAULT_SECTION_IMAGES);
  const [socialLinks, setSocialLinks] = useState<SocialLinks>(DEFAULT_SOCIAL_LINKS);
  const [contactConfig, setContactConfig] = useState<ContactConfig>(DEFAULT_CONTACT_CONFIG);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [partners, setPartners] = useState<Partner[]>([]);
  const [googleMapsLink, setGoogleMapsLink] = useState<string>("");
  const [gasUrl, setGasUrl] = useState<string>(FIXED_GAS_URL);

  const fetchFromCloud = async (url: string) => {
    if (!url) return;
    setCloudStatus('loading');
    try {
      const response = await fetch(url, { cache: 'no-store' });
      const data = await response.json();
      if (data && data.slides) {
        setSlides(data.slides);
        setSectionImages(data.sectionImages || DEFAULT_SECTION_IMAGES);
        setSocialLinks(data.socialLinks || DEFAULT_SOCIAL_LINKS);
        setContactConfig(data.emailConfig || DEFAULT_CONTACT_CONFIG);
        setNotices(data.notices || []);
        setReviews(data.reviews || []);
        setPartners(data.partners || []);
        setGoogleMapsLink(data.googleMapsLink || "");
        setCloudStatus('connected');
        return true;
      }
      return false;
    } catch (err) {
      setCloudStatus('error');
      return false;
    }
  };

  const publishToCloud = async (url: string) => {
    if (!url) return;
    setIsSyncing(true);
    setCloudStatus('loading');
    try {
      const payload = { slides, sectionImages, socialLinks, emailConfig: contactConfig, notices, reviews, partners, googleMapsLink };
      await fetch(url, { method: 'POST', mode: 'no-cors', body: JSON.stringify(payload) });
      setCloudStatus('connected');
      setTimeout(() => setIsSyncing(false), 2000);
      return true;
    } catch (err) {
      setCloudStatus('error');
      setIsSyncing(false);
      return false;
    }
  };

  useEffect(() => {
    const init = async () => {
      const local = localStorage.getItem(`${STORAGE_KEY_PREFIX}_slides`);
      if (local) {
        setSlides(JSON.parse(local));
        setContactConfig(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_contact_config`) || JSON.stringify(DEFAULT_CONTACT_CONFIG)));
      }
      fetchFromCloud(FIXED_GAS_URL).then(() => setIsInitialLoading(false));
    };
    init();
  }, []);

  useEffect(() => {
    if (!isInitialLoading) {
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_slides`, JSON.stringify(slides));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_contact_config`, JSON.stringify(contactConfig));
    }
  }, [slides, contactConfig, isInitialLoading]);

  const [currentSlide, setCurrentSlide] = useState(0);
  const t = translations[lang];

  useEffect(() => {
    const interval = setInterval(() => setCurrentSlide(p => (p + 1) % (slides.length || 1)), 9000);
    return () => clearInterval(interval);
  }, [slides]);

  const handleHeroButtonClick = (link?: string) => {
    if (!link) { setView('contact'); return; }
    const internalViews: View[] = ['home', 'contact', 'about', 'careers'];
    if (internalViews.includes(link as View)) { setView(link as View); window.scrollTo(0,0); }
    else if (link.startsWith('http')) window.open(link, '_blank');
    else setView('contact');
  };

  const handleContactSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFormStatus('sending');
    setTimeout(() => {
      setFormStatus('success');
      setTimeout(() => {
        setContactName(''); setContactEmail(''); setContactPhone(''); setContactMessage('');
        setFormStatus('idle');
      }, 3000);
    }, 1500);
  };

  // --- Admin Handlers ---
  // Fix: Implemented handleLogin to process administrative authentication
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (username === 'admin' && password === 'sir') {
      setIsAuthenticated(true);
      setIsLoginOpen(false);
      setIsAdminOpen(true);
      setLoginError(false);
      setUsername('');
      setPassword('');
    } else {
      setLoginError(true);
    }
  };

  const formatWhatsAppLink = (phone: string) => {
    const cleanPhone = phone.replace(/\D/g, '');
    return `https://wa.me/${cleanPhone}`;
  };

  return (
    <div className="min-h-screen bg-[#081221]">
      <AnimatePresence>{isInitialLoading && <InitialLoader />}</AnimatePresence>

      <header className="fixed top-0 w-full z-[900] glass-nav">
        <div className="px-8 md:px-16 py-4 flex justify-between items-center">
          <div onClick={() => setView('home')} className="cursor-pointer flex flex-col">
            <span className="text-xl md:text-2xl font-light tracking-[0.3em] text-white uppercase">ROSIMEIRE</span>
            <span className="text-[8px] font-bold tracking-[0.5em] text-[#f8c8c4] uppercase">SERVIÇOS</span>
          </div>
          <div className="hidden lg:flex items-center gap-8">
            <button onClick={() => setView('contact')} className="btn-serenity !py-2 !px-6">{t.navContact}</button>
            <button onClick={() => setIsLoginOpen(true)} className="text-white/20 hover:text-[#f8c8c4] transition-all"><Settings size={14} /></button>
          </div>
          <button className="lg:hidden text-white/60" onClick={() => setIsMenuOpen(!isMenuOpen)}><Menu size={28} /></button>
        </div>
      </header>

      <AnimatePresence mode="wait">
        {!isInitialLoading && view === 'home' && (
          <motion.div key="home" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            <section className="h-screen relative flex items-center overflow-hidden">
               <AnimatePresence mode="wait">
                <motion.div key={currentSlide} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} transition={{ duration: 2 }} className="absolute inset-0">
                   <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${slides[currentSlide]?.image})` }} />
                   <div className="absolute inset-0 bg-gradient-to-r from-[#081221] via-[#081221]/60 to-transparent" />
                </motion.div>
              </AnimatePresence>
              <div className="container mx-auto px-8 md:px-32 relative z-10">
                <motion.div initial={{ y: 20 }} animate={{ y: 0 }} className="max-w-4xl">
                  <span className="tagline block mb-4">{slides[currentSlide]?.tag}</span>
                  <h1 className="heading-serif text-5xl md:text-8xl text-white mb-6 uppercase leading-none">{slides[currentSlide]?.title}</h1>
                  <p className="text-white/50 text-lg mb-8 max-w-lg">{slides[currentSlide]?.description}</p>
                  <button onClick={() => handleHeroButtonClick(slides[currentSlide]?.buttonLink)} className="btn-serenity">
                    {slides[currentSlide]?.buttonText || t.navContact}
                  </button>
                </motion.div>
              </div>
            </section>
          </motion.div>
        )}

        {view === 'contact' && (
          <motion.div key="contact" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} className="pt-48 pb-64">
            <div className="container mx-auto px-8 md:px-16">
              <button onClick={() => setView('home')} className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-[#f8c8c4] mb-16"><ArrowLeft size={16} /> {t.back}</button>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-24">
                <div className="space-y-16">
                   <h2 className="heading-serif text-6xl md:text-8xl text-white uppercase">{t.quoteTitle}</h2>
                   <div className="space-y-12">
                     <div className="flex items-start gap-8">
                       <MapPin className="text-[#f8c8c4]/40 mt-1" size={24} />
                       <div>
                         <label className="tagline block mb-2">{t.addressTitle}</label>
                         <p className="text-xl font-light text-white/60 leading-relaxed">{contactConfig.address}</p>
                       </div>
                     </div>
                     <div className="flex items-start gap-8">
                       <Mail className="text-[#f8c8c4]/40 mt-1" size={24} />
                       <div>
                         <label className="tagline block mb-2">E-mail</label>
                         <a href={`mailto:${contactConfig.recipientEmail}`} className="text-2xl font-light text-[#f8c8c4] hover:brightness-110 transition-all underline underline-offset-8 decoration-white/10">{contactConfig.recipientEmail}</a>
                       </div>
                     </div>
                     <div className="flex items-start gap-8">
                       <Phone className="text-[#f8c8c4]/40 mt-1" size={24} />
                       <div className="flex flex-col gap-6">
                         <div>
                           <label className="tagline block mb-2">{t.phone}</label>
                           <p className="text-3xl font-light text-white">{contactConfig.phone}</p>
                         </div>
                         <a 
                           href={formatWhatsAppLink(contactConfig.phone)} 
                           target="_blank" 
                           rel="noopener noreferrer"
                           className="flex items-center gap-4 bg-[#25D366]/10 border border-[#25D366]/30 text-[#25D366] px-6 py-4 rounded-sm hover:bg-[#25D366]/20 transition-all w-fit group"
                         >
                           <MessageCircle size={20} className="group-hover:scale-110 transition-transform" />
                           <span className="text-[10px] font-black tracking-[0.3em] uppercase">Iniciar Conversa no WhatsApp</span>
                         </a>
                       </div>
                     </div>
                   </div>
                </div>
                <div className="crystal-card p-12 md:p-16 rounded-sm">
                  <form onSubmit={handleContactSubmit} className="space-y-12">
                    <div className="space-y-2">
                      <label className="tagline block">{t.name}</label>
                      <input required value={contactName} onChange={e => setContactName(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                    </div>
                    <div className="space-y-2">
                      <label className="tagline block">{t.email}</label>
                      <input type="email" required value={contactEmail} onChange={e => setContactEmail(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                    </div>
                    <div className="space-y-2">
                      <label className="tagline block">{t.phone}</label>
                      <div className="flex items-center border-b border-white/10 gap-4">
                        <select className="bg-transparent text-2xl py-4 outline-none" value={selectedCountry.code} onChange={e => setSelectedCountry(COUNTRY_CODES.find(c => c.code === e.target.value) || COUNTRY_CODES[0])}>
                          {COUNTRY_CODES.map(c => <option key={c.code} value={c.code} className="bg-[#081221]">{c.flag} {c.code}</option>)}
                        </select>
                        <input type="tel" required placeholder="9xx xxx xxx" value={contactPhone} onChange={e => setContactPhone(e.target.value.replace(/\D/g, ''))} className="w-full bg-transparent py-4 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                      </div>
                    </div>
                    <div className="space-y-2">
                      <label className="tagline block">{t.message}</label>
                      <textarea required rows={4} value={contactMessage} onChange={e => setContactMessage(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4] transition-all" />
                    </div>
                    <button type="submit" disabled={formStatus !== 'idle'} className="w-full btn-serenity py-8 flex justify-center items-center">
                      {formStatus === 'idle' ? t.send : (formStatus === 'sending' ? <Loader2 className="animate-spin"/> : <div className="flex items-center gap-3 text-green-400"><CheckCircle2 /> {t.success}</div>)}
                    </button>
                  </form>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AdminPanel 
        isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
        slides={slides} setSlides={setSlides}
        sectionImages={sectionImages} setSectionImages={setSectionImages}
        socialLinks={socialLinks} setSocialLinks={setSocialLinks}
        emailConfig={contactConfig} setEmailConfig={setContactConfig}
        notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews}
        partners={partners} setPartners={setPartners}
        googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink}
        activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={t}
        isSyncing={isSyncing} onResetDefaults={() => localStorage.clear()}
        gasUrl={gasUrl} setGasUrl={setGasUrl} onPublishToCloud={() => publishToCloud(gasUrl)}
        cloudStatus={cloudStatus}
      />

      <AnimatePresence>
        {isLoginOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1200] flex items-center justify-center bg-[#081221]/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="crystal-card p-12 max-w-sm w-full">
              <h3 className="heading-serif text-2xl text-center mb-8 uppercase tracking-widest text-white">SIR ADMIN</h3>
              <form onSubmit={handleLogin} className="space-y-6">
                <input placeholder="Utilizador" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none text-white" />
                <input placeholder="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none text-white" />
                {loginError && <p className="text-red-400 text-[10px] text-center uppercase tracking-widest">Acesso Negado</p>}
                <button type="submit" className="w-full btn-serenity">ENTRAR</button>
                <button onClick={() => setIsLoginOpen(false)} type="button" className="w-full text-xs text-white/20 uppercase mt-4">CANCELAR</button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-24 bg-[#040911] border-t border-white/5">
        <div className="container mx-auto px-8 text-center text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">© 2025. Rosimeire Serviços - Algarve.</div>
      </footer>
    </div>
  );
};

const InitialLoader = () => (
  <motion.div exit={{ opacity: 0 }} className="fixed inset-0 z-[2000] bg-[#081221] flex flex-col items-center justify-center">
    <div className="flex flex-col items-center">
      <span className="text-2xl font-light tracking-[0.4em] text-white uppercase">ROSIMEIRE</span>
      <span className="text-[10px] font-bold tracking-[0.6em] text-[#f8c8c4] uppercase mt-2">SERVIÇOS</span>
    </div>
  </motion.div>
);

createRoot(document.getElementById('root')!).render(<App />);

