                      className="w-full btn-serenity py-8 flex items-center justify-center gap-4 transition-all relative overflow-hidden"
                    >
                      <AnimatePresence mode="wait">
                        {formStatus === 'idle' && (
                          <motion.span key="idle" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                            {t.send}
                          </motion.span>
                        )}
                        {formStatus === 'sending' && (
                          <motion.div key="sending" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                            <Loader2 className="animate-spin" />
                          </motion.div>
                        )}
                        {formStatus === 'success' && (
                          <motion.div key="success" initial={{ y: 20 }} animate={{ y: 0 }} className="flex items-center gap-3 text-green-400">
                            <CheckCircle2 /> {t.success}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </button>
                  </form>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AdminPanel 
        isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
        slides={slides} setSlides={setSlides}
        sectionImages={sectionImages} setSectionImages={setSectionImages}
        socialLinks={socialLinks} setSocialLinks={setSocialLinks}
        emailConfig={emailConfig} setEmailConfig={setEmailConfig}
        notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews}
        partners={partners} setPartners={setPartners}
        googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink}
        activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={t}
        isSyncing={isSyncing} onResetDefaults={handleResetDefaults}
        gasUrl={gasUrl} setGasUrl={setGasUrl} onPublishToCloud={() => publishToCloud(gasUrl)}
        cloudStatus={cloudStatus}
      />

      <AnimatePresence>
        {isLoginOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1200] flex items-center justify-center bg-[#081221]/80 backdrop-blur-md">
            <motion.div initial={{ scale: 0.9 }} animate={{ scale: 1 }} className="crystal-card p-12 max-w-sm w-full">
              <h3 className="heading-serif text-2xl text-center mb-8 uppercase tracking-widest">Acesso Restrito</h3>
              <form onSubmit={handleLogin} className="space-y-6">
                <input placeholder="Utilizador" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none" />
                <input placeholder="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none" />
                <button type="submit" className="w-full btn-serenity">Entrar</button>
                <button onClick={() => setIsLoginOpen(false)} type="button" className="w-full text-xs text-white/20 uppercase mt-4">Cancelar</button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <footer className="py-24 bg-[#040911] border-t border-white/5">
        <div className="container mx-auto px-8 md:px-16 text-center">
          <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">© 2025. Rosimeire Serviços - Algarve.</p>
        </div>
      </footer>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);

import React, { useState, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Settings, Trash2, Plus, Save, Bell, X, Star, User, Link as LinkIcon, 
  Briefcase, CheckCircle, Image as ImageIcon, RotateCcw, Cloud, Mail, 
  Key, Server, Eye, EyeOff, ShieldCheck, Zap, AlertCircle, Loader2, 
  Info, Lightbulb, Check, Database, Download, Upload, FileJson, ExternalLink, Link, RefreshCw, CloudOff,
  Instagram, Linkedin, Palette, MessageSquare, MessageCircle, Phone
} from 'lucide-react';

interface Slide {
  id: string;
  title: string;
  description: string;
  image: string;
  tag: string;
  buttonLink?: string;
  buttonText?: string;
}

interface SectionImages {
  about: string;
  careers: string;
}

interface SocialLinks {
  instagram: string;
  linkedin: string;
}

interface EmailConfig {
  recipientEmail: string;
  phone: string;
  serviceId: string;
  templateId: string;
  publicKey: string;
  smtpHost: string;
  smtpPort: string;
  smtpUser: string;
  smtpPass: string;
  smtpSecure: boolean;
  useSmtp: boolean;
}

interface Notice {
  id: string;
  text: string;
  active: boolean;
}

interface Review {
  id: string;
  author: string;
  text: string;
  time: string;
  avatar?: string;
  initials: string;
  color: string;
}

interface Partner {
  id: string;
  name: string;
  logo: string;
  url: string;
}

interface AdminPanelProps {
  isOpen: boolean;
  onClose: () => void;
  onLogout: () => void;
  slides: Slide[];
  setSlides: (slides: Slide[]) => void;
  sectionImages: SectionImages;
  setSectionImages: (imgs: SectionImages) => void;
  socialLinks: SocialLinks;
  setSocialLinks: (links: SocialLinks) => void;
  emailConfig: EmailConfig;
  setEmailConfig: (config: EmailConfig) => void;
  notices: Notice[];
  setNotices: (notices: Notice[]) => void;
  reviews: Review[];
  setReviews: (reviews: Review[]) => void;
  partners: Partner[];
  setPartners: (partners: Partner[]) => void;
  googleMapsLink: string;
  setGoogleMapsLink: (link: string) => void;
  activeTab: 'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email';
  setActiveTab: (tab: any) => void;
  t: any;
  isSyncing: boolean;
  onResetDefaults: () => void;
  gasUrl: string;
  setGasUrl: (url: string) => void;
  onPublishToCloud: () => Promise<boolean>;
  cloudStatus: 'idle' | 'loading' | 'connected' | 'error';
}

const AdminPanel: React.FC<AdminPanelProps> = ({
  isOpen, onClose, onLogout, slides, setSlides, sectionImages, setSectionImages, socialLinks, setSocialLinks, emailConfig, setEmailConfig, notices, setNotices, reviews, setReviews, 
  partners, setPartners, googleMapsLink, setGoogleMapsLink, activeTab, setActiveTab, t, isSyncing, onResetDefaults, gasUrl, setGasUrl, onPublishToCloud, cloudStatus
