        {view === 'contact' && (
          <motion.div key="contact" initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} className="pt-48 pb-64">
            <div className="container mx-auto px-8 md:px-16">
              <button onClick={() => setView('home')} className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-[#f8c8c4] transition-all mb-16 group"><ArrowLeft size={16} /> {t.back}</button>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-24">
                <div className="space-y-12">
                   <h2 className="heading-serif text-6xl text-white">{t.quoteTitle}</h2>
                   <div className="space-y-8">
                     <div className="flex items-start gap-6">
                        <MapPin className="text-[#f8c8c4]/40 mt-1" />
                        <div>
                          <p className="text-[10px] font-bold tracking-[0.3em] text-white/20 uppercase mb-1">{t.addressTitle}</p>
                          <p className="text-xl font-light text-white/60">{emailConfig.address || t.addressDetail}</p>
                        </div>
                     </div>
                     <div className="flex items-start gap-6">
                        <Mail className="text-[#f8c8c4]/40 mt-1" />
                        <div>
                          <p className="text-[10px] font-bold tracking-[0.3em] text-white/20 uppercase mb-1">E-mail</p>
                          <a href={`mailto:${emailConfig.recipientEmail}`} className="text-xl font-light text-[#f8c8c4] hover:text-white transition-colors underline underline-offset-4 decoration-white/10">
