      setTimeout(() => {
        handleClearForm();
        setFormStatus('idle');
      }, 3000);
    }, 1500);
  };

  const handleClearForm = () => {
    setContactName('');
    setContactEmail('');
    setContactPhone('');
    setContactMessage('');
  };

