                      <input value={emailConfig.phone} onChange={e => updateEmailConfig('phone', e.target.value)} placeholder="+351 912 525 649" className="admin-input" />
                    </div>
                    <div className="space-y-2">
                      <label className="admin-label flex items-center gap-2"><MapPin size={10}/> Morada / Escritório</label>
                      <input value={emailConfig.address} onChange={e => updateEmailConfig('address', e.target.value)} placeholder="Endereço Completo" className="admin-input" />
