  { id: '2', author: "Alex Alcivar", text: "Auténtico profesionales en el sector!! Cuidan cada detalle.", time: "12 meses atrás", initials: "AA", color: "#1a365d" }
];

const FIXED_GAS_URL = "https://script.google.com/macros/s/AKfycbzsOBqT_YLZW576jbHX8vAcuBi4bSNhn4CYdqTwcu7ObX6QcqNIhjXlsOYxlud9nqy6/exec";
const SIR_URL = "https://sir.rosimeireservicos.com"; 

const InitialLoader = () => (
  <motion.div initial={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[2000] bg-[#081221] flex flex-col items-center justify-center gap-8">
    <div className="flex flex-col items-center">
      <motion.span initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="text-2xl md:text-3xl font-light tracking-[0.4em] text-white uppercase">ROSIMEIRE</motion.span>
      <motion.span initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="text-[10px] font-bold tracking-[0.6em] text-[#f8c8c4] uppercase mt-2">SERVIÇOS</motion.span>
    </div>
    <div className="w-48 h-[1px] bg-white/5 relative overflow-hidden">
      <motion.div initial={{ x: '-100%' }} animate={{ x: '100%' }} transition={{ repeat: Infinity, duration: 2, ease: "linear" }} className="absolute inset-0 bg-gradient-to-r from-transparent via-[#f8c8c4] to-transparent" />
    </div>
  </motion.div>
);

const App = () => {
  const [lang, setLang] = useState<Language>('PT');
  const [view, setView] = useState<View>('home');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isAdminOpen, setIsAdminOpen] = useState(false);
  const [isLoginOpen, setIsLoginOpen] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [activeAdminTab, setActiveAdminTab] = useState<'slides' | 'notices' | 'reviews' | 'partners' | 'images' | 'email' | 'users'>('slides');
  const [isSyncing, setIsSyncing] = useState(false);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [cloudStatus, setCloudStatus] = useState<'idle' | 'loading' | 'connected' | 'error'>('idle');

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loginError, setLoginError] = useState(false);

  const [contactName, setContactName] = useState('');
  const [contactEmail, setContactEmail] = useState('');
  const [contactPhone, setContactPhone] = useState('');
  const [contactMessage, setContactMessage] = useState('');

  const STORAGE_KEY_PREFIX = 'rosimeire_config_v12';

  const [slides, setSlides] = useState<Slide[]>(DEFAULT_SLIDES);
  const [sectionImages, setSectionImages] = useState<SectionImages>(DEFAULT_SECTION_IMAGES);
  const [socialLinks, setSocialLinks] = useState<SocialLinks>(DEFAULT_SOCIAL_LINKS);
  const [emailConfig, setEmailConfig] = useState<EmailConfig>(DEFAULT_EMAIL_CONFIG);
  const [notices, setNotices] = useState<Notice[]>(DEFAULT_NOTICES);
  const [reviews, setReviews] = useState<Review[]>(DEFAULT_REVIEWS);
  const [partners, setPartners] = useState<Partner[]>(DEFAULT_PARTNERS);
  const [users, setUsers] = useState<UserAccount[]>([]);
  const [googleMapsLink, setGoogleMapsLink] = useState<string>("");
  const [gasUrl, setGasUrl] = useState<string>(FIXED_GAS_URL);

  const [currentSlide, setCurrentSlide] = useState(0);
  const [currentReviewIndex, setCurrentReviewIndex] = useState(0);
  const [currentPartnerIndex, setCurrentPartnerIndex] = useState(0);
  const [formStatus, setFormStatus] = useState<'idle' | 'sending' | 'success'>('idle');

  const fetchFromCloud = async (url: string) => {
    if (!url) return;
    setCloudStatus('loading');
    try {
      const response = await fetch(url, { cache: 'no-store' });
      const data = await response.json();
      if (data && data.slides) {
        setSlides(data.slides);
        setSectionImages(data.sectionImages || DEFAULT_SECTION_IMAGES);
        setSocialLinks(data.socialLinks || DEFAULT_SOCIAL_LINKS);
        setEmailConfig(data.emailConfig || DEFAULT_EMAIL_CONFIG);
        setNotices(data.notices || DEFAULT_NOTICES);
        setReviews(data.reviews || DEFAULT_REVIEWS);
        setPartners(data.partners || DEFAULT_PARTNERS);
        setUsers(data.users || []);
        setGoogleMapsLink(data.googleMapsLink || "");
        setCloudStatus('connected');
        return true;
      }
      return false;
    } catch (err) {
      setCloudStatus('error');
      return false;
    }
  };

  const publishToCloud = async (url: string) => {
    if (!url) return;
    setIsSyncing(true);
    setCloudStatus('loading');
    try {
      const payload = { slides, sectionImages, socialLinks, emailConfig, notices, reviews, partners, users, googleMapsLink, version: "1.2", lastSync: new Date().toISOString() };
      await fetch(url, { method: 'POST', mode: 'no-cors', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify(payload) });
      setCloudStatus('connected');
      setTimeout(() => setIsSyncing(false), 2000);
      return true;
    } catch (err) {
      setCloudStatus('error');
      setIsSyncing(false);
      return false;
    }
  };

  useEffect(() => {
    const initApp = async () => {
      const localSlides = localStorage.getItem(`${STORAGE_KEY_PREFIX}_slides`);
      if (localSlides) {
        setSlides(JSON.parse(localSlides));
        setSectionImages(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_section_images`) || JSON.stringify(DEFAULT_SECTION_IMAGES)));
        setSocialLinks(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_social_links`) || JSON.stringify(DEFAULT_SOCIAL_LINKS)));
        setEmailConfig(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_email_config`) || JSON.stringify(DEFAULT_EMAIL_CONFIG)));
        setNotices(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_notices`) || JSON.stringify(DEFAULT_NOTICES)));
        setReviews(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_reviews`) || JSON.stringify(DEFAULT_REVIEWS)));
        setPartners(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_partners`) || JSON.stringify(DEFAULT_PARTNERS)));
        setUsers(JSON.parse(localStorage.getItem(`${STORAGE_KEY_PREFIX}_users`) || "[]"));
        setGoogleMapsLink(localStorage.getItem(`${STORAGE_KEY_PREFIX}_maps`) || "");
      }
      setTimeout(() => setIsInitialLoading(false), 800);
      fetchFromCloud(FIXED_GAS_URL);
    };
    initApp();
  }, []);

  useEffect(() => {
    if (!isInitialLoading) {
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_slides`, JSON.stringify(slides));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_section_images`, JSON.stringify(sectionImages));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_social_links`, JSON.stringify(socialLinks));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_email_config`, JSON.stringify(emailConfig));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_notices`, JSON.stringify(notices));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_reviews`, JSON.stringify(reviews));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_partners`, JSON.stringify(partners));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_users`, JSON.stringify(users));
      localStorage.setItem(`${STORAGE_KEY_PREFIX}_maps`, googleMapsLink);
    }
  }, [slides, sectionImages, socialLinks, emailConfig, notices, reviews, partners, users, googleMapsLink, isInitialLoading]);

  const t = translations[lang];

  useEffect(() => {
    const interval = setInterval(() => setCurrentSlide(p => (p + 1) % (slides.length || 1)), 9000);
    return () => clearInterval(interval);
  }, [slides]);

  const handleHeroButtonClick = (link?: string) => {
    if (!link) { setView('contact'); return; }
    if (['home', 'contact', 'about', 'careers'].includes(link)) { setView(link as View); window.scrollTo({ top: 0, behavior: 'smooth' }); }
    else if (link.startsWith('http')) window.open(link, '_blank');
    else setView('contact');
  };

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const isMaster = username === 'admin' && password === 'rosimeire2025';
    const isDynamic = users.some(u => u.username === username && u.password === password);
    if (isMaster || isDynamic) { setIsAuthenticated(true); setIsLoginOpen(false); setIsAdminOpen(true); }
    else setLoginError(true);
  };

  const handleContactSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setFormStatus('sending');
    setTimeout(() => { setFormStatus('success'); setTimeout(() => setFormStatus('idle'), 5000); }, 2000);
  };

  const getWhatsAppLink = (p: string) => `https://wa.me/${(p || '').replace(/\D/g, '')}`;

  return (
    <div className="min-h-screen selection:bg-[#f8c8c4] selection:text-[#081221]">
      <AnimatePresence>{isInitialLoading && <InitialLoader />}</AnimatePresence>

      <div className={`fixed top-0 w-full flex flex-col transition-all duration-500 ${isMenuOpen ? 'z-[1000]' : 'z-[900]'}`}>
        <AnimatePresence>
          {notices.filter(n => n.active).map((notice) => (
            <motion.button key={notice.id} initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} onClick={() => setView('contact')} className="w-full bg-[#f8c8c4] text-[#081221] py-3 px-8 flex justify-center items-center gap-6 relative cursor-pointer outline-none">
              <Bell size={18} strokeWidth={2.5} />
              <span className="text-[10px] md:text-[11px] font-black tracking-[0.3em] uppercase text-center leading-tight">{notice.text}</span>
            </motion.button>
          ))}
        </AnimatePresence>

        <header className={`transition-all duration-500 ${isMenuOpen ? 'bg-transparent' : 'glass-nav border-b border-white/5 shadow-2xl'}`}>
          <div className="px-8 md:px-16 py-4 flex justify-between items-center">
            <div className="flex flex-col cursor-pointer" onClick={() => setView('home')}>
              <span className="text-xl md:text-2xl font-light tracking-[0.3em] text-white uppercase">ROSIMEIRE</span>
              <span className="text-[8px] font-bold tracking-[0.5em] text-[#f8c8c4] uppercase mt-1">SERVIÇOS</span>
            </div>
            <div className="hidden lg:flex items-center gap-8">
              {['PT', 'EN', 'ES'].map(l => (
                <button key={l} onClick={() => setLang(l as Language)} className={`text-[8px] font-black tracking-widest ${lang === l ? 'text-[#f8c8c4]' : 'text-white/10 hover:text-white/40'}`}>{l}</button>
              ))}
              <div className="w-[1px] h-3 bg-white/5"></div>
              <button onClick={() => setView('contact')} className={`btn-serenity !py-2 !px-6 ${view === 'contact' ? 'bg-[#f8c8c4] text-[#081221]' : ''}`}>{t.navContact}</button>
              <button onClick={() => window.open(SIR_URL, '_blank')} className="group flex items-center gap-2 text-[10px] font-black text-white/30 hover:text-[#f8c8c4] transition-all"><Zap size={12}/> SIR</button>
              <button onClick={() => isAuthenticated ? setIsAdminOpen(true) : setIsLoginOpen(true)} className="text-white/20 hover:text-[#f8c8c4]"><Settings size={14} /></button>
            </div>
            <button className="lg:hidden relative z-[1100] text-white/60" onClick={() => setIsMenuOpen(!isMenuOpen)}>{isMenuOpen ? <X size={28} /> : <Menu size={28} />}</button>
          </div>
        </header>
      </div>

      <AnimatePresence>
        {isMenuOpen && (
          <motion.div initial={{ opacity: 0, x: '100%' }} animate={{ opacity: 1, x: 0 }} exit={{ opacity: 0, x: '100%' }} className="fixed inset-0 z-[1050] bg-[#081221] pt-32 px-12 pb-24 flex flex-col justify-between">
            <nav className="flex flex-col gap-10">
              {[{ label: t.navHome, view: 'home' }, { label: t.footerSobre, view: 'about' }, { label: t.footerCarreira, view: 'careers' }, { label: t.navContact, view: 'contact' }].map((item) => (
                <button key={item.view} onClick={() => { setView(item.view as View); setIsMenuOpen(false); }} className="text-left text-3xl font-light tracking-[0.2em] text-white/80 hover:text-[#f8c8c4] uppercase">{item.label}</button>
              ))}
            </nav>
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {!isInitialLoading && view === 'home' && (
          <motion.div key="home" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
            {/* Hero */}
            <section className="min-h-screen h-screen relative flex overflow-hidden group/hero">
              <AnimatePresence mode="wait">
                <motion.div key={currentSlide} initial={{ opacity: 0, scale: 1.05 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} transition={{ duration: 2 }} className="absolute inset-0">
                  <div className="absolute inset-0 bg-cover bg-center" style={{ backgroundImage: `url(${slides[currentSlide]?.image})` }} />
                  <div className="absolute inset-0 bg-gradient-to-r from-[#081221] via-[#081221]/60 to-transparent" />
                </motion.div>
              </AnimatePresence>
              <div className="container mx-auto px-8 md:px-32 relative z-10 flex flex-col justify-center h-full pt-32">
                <motion.div key={`c-${currentSlide}`} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="max-w-4xl">
                  <span className="tagline tagline-hero mb-3 block">{slides[currentSlide]?.tag}</span>
                  <h1 className="heading-serif text-4xl md:text-6xl lg:text-[5.5rem] text-white mb-5 uppercase tracking-tighter leading-tight">
                    {slides[currentSlide]?.title.split(' ')[0]}<br/>
                    <span className="italic font-light opacity-60 text-[#f8c8c4]">{slides[currentSlide]?.title.split(' ').slice(1).join(' ')}</span>
                  </h1>
                  <p className="text-xs md:text-lg font-light text-white/50 max-w-lg leading-relaxed mb-8">{slides[currentSlide]?.description}</p>
                  <button onClick={() => handleHeroButtonClick(slides[currentSlide]?.buttonLink)} className="btn-serenity w-fit !px-8 !py-3">{slides[currentSlide]?.buttonText || t.navContact}</button>
                </motion.div>
              </div>
            </section>

            <GlassDivider />

            {/* Services */}
            <section className="py-32 md:py-64 relative">
              <div className="container mx-auto px-8 md:px-16">
                <div className="max-w-3xl mb-32">
                  <span className="tagline mb-10 block">{t.servicesTitle}</span>
                  <h2 className="heading-serif text-6xl md:text-[9rem] text-white leading-none">{t.servicesSubtitle}</h2>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                  {[
                    { title: t.s1Title, tagline: t.s1Tagline, desc: t.s1Desc, icon: <Building2 size={32}/> },
                    { title: t.s2Title, tagline: t.s2Tagline, desc: t.s2Desc, icon: <Home size={32}/> },
                    { title: t.s3Title, tagline: t.s3Tagline, desc: t.s3Desc, icon: <Sparkle size={32}/> },
                    { title: t.s4Title, tagline: t.s4Tagline, desc: t.s4Desc, icon: <Paintbrush size={32}/> }
                  ].map((s, idx) => (
                    <div key={idx} className="crystal-card p-14 rounded-sm group h-auto min-h-[500px] flex flex-col justify-between">
                       <div className="space-y-10">
                         <div className="text-[#f8c8c4]/60">{s.icon}</div>
                         <h3 className="text-3xl font-light text-white tracking-tighter uppercase leading-tight">{s.title}</h3>
                         <p className="text-[#f8c8c4]/80 text-[11px] font-bold uppercase tracking-[0.4em] italic leading-relaxed">{s.tagline}</p>
                         <p className="text-white/50 text-base font-light leading-relaxed">{s.desc}</p>
                       </div>
                    </div>
                  ))}
                </div>
              </div>
            </section>

            <GlassDivider />

            {/* Reviews Section RESTAURADA */}
            {reviews.length > 0 && (
              <section className="py-32 md:py-64 relative">
                <div className="container mx-auto px-8 md:px-16 text-center">
                  <span className="tagline mb-12 block">{t.reviewsTitle}</span>
                  <div className="max-w-5xl mx-auto">
                    <AnimatePresence mode="wait">
                      <motion.div key={currentReviewIndex} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} className="flex flex-col items-center gap-12">
                        <div className="w-24 h-24 rounded-full flex items-center justify-center text-2xl font-bold text-white shadow-xl" style={{ backgroundColor: reviews[currentReviewIndex]?.color || '#f8c8c4' }}>{reviews[currentReviewIndex]?.initials}</div>
                        <p className="text-2xl md:text-4xl font-light text-white leading-relaxed italic opacity-80">"{reviews[currentReviewIndex]?.text}"</p>
                        <div className="space-y-2">
                          <h4 className="text-xl font-bold uppercase tracking-[0.2em] text-white">{reviews[currentReviewIndex]?.author}</h4>
                          <p className="text-[10px] font-bold tracking-[0.4em] text-[#f8c8c4] uppercase">{reviews[currentReviewIndex]?.time}</p>
                        </div>
                      </motion.div>
                    </AnimatePresence>
                    <div className="flex justify-center gap-12 mt-16">
                      <button onClick={() => setCurrentReviewIndex(p => (p - 1 + reviews.length) % reviews.length)} className="text-white/20 hover:text-[#f8c8c4]"><ChevronLeft size={32}/></button>
                      <button onClick={() => setCurrentReviewIndex(p => (p + 1) % reviews.length)} className="text-white/20 hover:text-[#f8c8c4]"><ChevronRight size={32}/></button>
                    </div>
                  </div>
                </div>
              </section>
            )}

            <GlassDivider />

            {/* Partners Section RESTAURADA */}
            {partners.length > 0 && (
              <section className="py-32 md:py-64 relative">
                <div className="container mx-auto px-8 md:px-16 text-center">
                  <span className="tagline mb-24 block">{t.partnersTitle}</span>
                  <div className="max-w-3xl mx-auto">
                    <AnimatePresence mode="wait">
                      <motion.div key={currentPartnerIndex} initial={{ opacity: 0, scale: 0.98 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0 }} className="flex justify-center">
                        <a href={partners[currentPartnerIndex]?.url} target="_blank" className="crystal-card p-0 rounded-sm flex flex-col overflow-hidden max-w-xl w-full border-[#f8c8c4]/10">
                          <div className="w-full h-48 md:h-72 relative overflow-hidden bg-white/[0.02]">
                            <img src={partners[currentPartnerIndex]?.logo} className="w-full h-full object-cover grayscale" />
                          </div>
                          <div className="p-8 text-center bg-[#081221]/60">
                            <h4 className="text-lg font-light text-white tracking-[0.3em] uppercase">{partners[currentPartnerIndex]?.name}</h4>
                          </div>
                        </a>
                      </motion.div>
                    </AnimatePresence>
                    <div className="flex justify-center gap-4 mt-12">
                      {partners.map((_, idx) => (
                        <button key={idx} onClick={() => setCurrentPartnerIndex(idx)} className={`h-[1px] transition-all duration-700 ${idx === currentPartnerIndex ? 'w-16 bg-[#f8c8c4]' : 'w-4 bg-white/10'}`} />
                      ))}
                    </div>
                  </div>
                </div>
              </section>
            )}
          </motion.div>
        )}

        {view === 'about' && (
          <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} className="pt-48 pb-64">
             <div className="container mx-auto px-8 md:px-16">
               <button onClick={() => setView('home')} className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-[#f8c8c4] mb-16"><ArrowLeft size={16} /> {t.back}</button>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-24 items-center">
                <div>
                  <span className="tagline mb-8 block">{t.aboutSectionTitle}</span>
                  <h2 className="heading-serif text-5xl md:text-8xl text-white mb-12 uppercase leading-none">SOBRE<br/><span className="italic text-[#f8c8c4]/60 font-light">Rosimeire</span></h2>
                  <p className="text-xl font-light text-white/60 leading-relaxed max-w-xl">{t.aboutSectionText}</p>
                </div>
                <img src={sectionImages.about} className="w-full h-[600px] object-cover rounded-sm border border-white/5 shadow-2xl" />
              </div>
            </div>
          </motion.div>
        )}

        {view === 'careers' && (
          <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} className="pt-48 pb-64">
            <div className="container mx-auto px-8 md:px-16">
               <button onClick={() => setView('home')} className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-[0.4em] text-white/20 hover:text-[#f8c8c4] mb-16"><ArrowLeft size={16} /> {t.back}</button>
              <h2 className="heading-serif text-5xl md:text-8xl text-white mb-12 uppercase leading-none">{t.careersHeroTitle}</h2>
              <div className="crystal-card p-16 rounded-sm text-center">
                 <h3 className="heading-serif text-4xl mb-8">{t.careersApplyTitle}</h3>
                 <a href={t.careersFormLink} target="_blank" className="btn-serenity inline-flex items-center gap-4">{t.careersApplyBtn} <ExternalLink size={14}/></a>
              </div>
            </div>
          </motion.div>
        )}

        {view === 'contact' && (
          <motion.div initial={{ opacity: 0, y: 30 }} animate={{ opacity: 1, y: 0 }} className="pt-48 pb-64">
            <div className="container mx-auto px-8 md:px-16">
              <button onClick={() => setView('home')} className="flex items-center gap-4 text-[10px] font-bold uppercase tracking-[0.4em] text-white/20 mb-16"><ArrowLeft size={16} /> {t.back}</button>
              <div className="grid grid-cols-1 lg:grid-cols-2 gap-24">
                <div className="space-y-12">
                   <h2 className="heading-serif text-6xl text-white">{t.quoteTitle}</h2>
                   <div className="space-y-8">
                     <div className="flex items-start gap-6">
                       <MapPin className="text-[#f8c8c4]/40 mt-1" />
                       <div className="flex flex-col"><span className="text-[10px] font-bold text-white/20 uppercase">Morada</span><p className="text-xl font-light text-white/60">{emailConfig.address}</p></div>
                     </div>
                     <div className="flex items-start gap-6">
                       <Mail className="text-[#f8c8c4]/40 mt-1" />
                       <div className="flex flex-col"><span className="text-[10px] font-bold text-white/20 uppercase">Email</span><p className="text-xl font-light text-white/60">{emailConfig.recipientEmail}</p></div>
                     </div>
                     <div className="flex items-start gap-6">
                       <Phone className="text-[#f8c8c4]/40 mt-1" />
                       <div className="flex flex-col gap-2">
                         <span className="text-[10px] font-bold text-white/20 uppercase">Telefone</span>
                         <div className="flex items-center gap-4">
                           <p className="text-2xl font-light text-white/80">{emailConfig.phone}</p>
                           <a href={getWhatsAppLink(emailConfig.phone)} target="_blank" className="w-10 h-10 flex items-center justify-center rounded-full bg-[#25D366]/10 text-[#25D366] hover:bg-[#25D366] hover:text-white transition-all"><MessageCircle size={20} /></a>
                         </div>
                       </div>
                     </div>
                   </div>
