                <div className="crystal-card p-12 rounded-sm">
                  <form onSubmit={handleContactSubmit} className="space-y-12">
                    <div className="space-y-2"><label className="tagline">{t.name}</label><input required value={contactName} onChange={e => setContactName(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4]" /></div>
                    <div className="space-y-2"><label className="tagline">{t.email}</label><input type="email" required value={contactEmail} onChange={e => setContactEmail(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4]" /></div>
                    <div className="space-y-2"><label className="tagline">{t.phone}</label><input type="tel" required value={contactPhone} onChange={e => setContactPhone(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4]" /></div>
                    <div className="space-y-2"><label className="tagline">{t.message}</label><textarea required rows={4} value={contactMessage} onChange={e => setContactMessage(e.target.value)} className="w-full bg-transparent border-b border-white/10 py-4 text-xl font-light outline-none focus:border-[#f8c8c4]" /></div>
                    <div className="flex flex-col gap-4">
                      <button className="w-full btn-serenity py-8">{formStatus === 'idle' ? t.send : (formStatus === 'sending' ? '...' : t.success)}</button>
                      <button type="button" onClick={() => { setContactName(''); setContactEmail(''); setContactPhone(''); setContactMessage(''); }} className="self-end text-[9px] font-bold text-white/20 hover:text-[#f8c8c4] uppercase">{t.clear}</button>
                    </div>
                  </form>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <AdminPanel 
        isOpen={isAdminOpen} onClose={() => setIsAdminOpen(false)} onLogout={() => { setIsAuthenticated(false); setIsAdminOpen(false); }}
        slides={slides} setSlides={setSlides} sectionImages={sectionImages} setSectionImages={setSectionImages}
        socialLinks={socialLinks} setSocialLinks={setSocialLinks} emailConfig={emailConfig} setEmailConfig={setEmailConfig}
        notices={notices} setNotices={setNotices} reviews={reviews} setReviews={setReviews} partners={partners} setPartners={setPartners}
        users={users} setUsers={setUsers} googleMapsLink={googleMapsLink} setGoogleMapsLink={setGoogleMapsLink}
        activeTab={activeAdminTab} setActiveTab={setActiveAdminTab} t={t} isSyncing={isSyncing} onResetDefaults={() => { localStorage.clear(); window.location.reload(); }}
        gasUrl={gasUrl} setGasUrl={setGasUrl} onPublishToCloud={() => publishToCloud(gasUrl)} cloudStatus={cloudStatus}
      />

      {/* Login Modal */}
      <AnimatePresence>
        {isLoginOpen && (
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[1200] flex items-center justify-center bg-[#081221]/80 backdrop-blur-md">
            <div className="crystal-card p-12 max-w-sm w-full">
              <h3 className="heading-serif text-2xl text-center mb-8 uppercase tracking-widest">Acesso Restrito</h3>
              <form onSubmit={handleLogin} className="space-y-6">
                <input placeholder="Utilizador" value={username} onChange={e => setUsername(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none" />
                <input placeholder="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-white/5 border border-white/10 p-4 rounded outline-none" />
                <button type="submit" className="w-full btn-serenity">Entrar</button>
                <button onClick={() => setIsLoginOpen(false)} type="button" className="w-full text-xs text-white/20 uppercase mt-4">Cancelar</button>
              </form>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* FOOTER REORGANIZADO EM GRADE DE 3 COLUNAS */}
      <footer className="py-24 bg-[#040911] border-t border-white/5">
        <div className="container mx-auto px-8 md:px-16">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-16 md:gap-24 mb-24">
            {/* Coluna 1: Nome e Tagline */}
            <div className="flex flex-col">
              <span className="text-2xl font-light tracking-[0.3em] text-white">ROSIMEIRE SERVIÇOS</span>
              <p className="text-white/30 text-[10px] font-bold uppercase tracking-[0.4em] mt-6 max-w-xs">{t.footerNote}</p>
            </div>

            {/* Coluna 2: Redes Sociais */}
            <div className="flex flex-col">
              <h4 className="text-[10px] font-black text-[#f8c8c4] uppercase tracking-[0.4em] mb-8">Redes Sociais</h4>
              <div className="flex gap-8">
                <a href={socialLinks.instagram} target="_blank" rel="noopener noreferrer" className="text-white/20 hover:text-[#f8c8c4] transition-all transform hover:scale-110"><Instagram size={24} /></a>
                <a href={socialLinks.linkedin} target="_blank" rel="noopener noreferrer" className="text-white/20 hover:text-[#f8c8c4] transition-all transform hover:scale-110"><Linkedin size={24} /></a>
              </div>
            </div>

            {/* Coluna 3: Sobre e Carreira */}
            <div className="flex flex-col">
              <h4 className="text-[10px] font-black text-[#f8c8c4] uppercase tracking-[0.4em] mb-8">Empresa</h4>
              <nav className="flex flex-col gap-6">
                <button onClick={() => setView('about')} className="text-left text-xs text-white/40 hover:text-[#f8c8c4] uppercase tracking-[0.3em]">{t.footerSobre}</button>
                <button onClick={() => setView('careers')} className="text-left text-xs text-white/40 hover:text-[#f8c8c4] uppercase tracking-[0.3em]">{t.footerCarreira}</button>
                <button onClick={() => setView('contact')} className="text-left text-xs text-white/40 hover:text-[#f8c8c4] uppercase tracking-[0.3em]">{t.navContact}</button>
              </nav>
            </div>
          </div>

          <div className="flex flex-col md:flex-row justify-between items-center gap-8 pt-12 border-t border-white/5">
            <p className="text-[9px] font-bold tracking-[0.4em] text-white/10 uppercase italic">© 2025. Rosimeire Serviços - Algarve.</p>
            <div className="flex flex-col items-center md:items-end gap-2 text-right">
              <span className="text-[7px] font-black tracking-[0.2em] text-white/10 uppercase">{t.developedBy}</span>
              <span className="text-[9px] font-bold tracking-[0.1em] text-white/20 uppercase">Bob Harrisson Gracindo Madeiro</span>
              <span className="text-[7px] font-medium tracking-[0.4em] text-[#f8c8c4]/30 uppercase italic">IT Depart.</span>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

createRoot(document.getElementById('root')!).render(<App />);
